            async get(k) { try { const db = await this.buka(); return await new Promise(ok => { const q = db.transaction('snap').objectStore('snap').get(k); q.onsuccess = () => ok(q.result || null); q.onerror = () => ok(null); }); } catch (e) { return null; } },
