  }
  if (!ubah.length) return { data: r, tidakBerubah: true };
  Object.assign(b, { diubahOleh: u.nama, diubahPada: now, versi: Number(r.versi) + 1 });
  return { data: b, detail: 'Tagihan ke-' + r.tagihanKe + ' (' + r.nomorBA + ') · ' + ubah.join('; ') };
}


