        (PMT.data || []).forEach(b => { const st = statusKontrakPermintaan(b); (b.items || []).forEach((it, i) => { if (!alok.has(b.nomor + '#' + i) && !st.sudah[i]) bonBelum.push({ b, it, i }); }); });
        const chip = (v, l, n) => `<button type="button" class="reg-chip ${PBJ.filter === v ? 'aktif' : ''}" onclick="PBJ.filter='${v}'; renderPBJ()">${l}<span class="n">${n}</span></button>`;
        const entri = bolehEntri() && PBJ.dukung !== false;
        el.innerHTML = bannerServer() + `
        <div class="row g-3 mb-3">
            ${[['Paket aktif', akt.length.toLocaleString('id-ID'), akt.filter(p => p.status === 'KONTRAK').length + ' sudah jadi kontrak', '#1763B3', 'fa-gavel'],
               ['Total HPS', rpS(hps), fmtRp(hps), '#0B2B54', 'fa-scale-balanced'],
               ['Harga final pemenang', rpS(fin), akt.filter(p => p.pemenang).length + ' paket ada pemenang', '#2E9E5B', 'fa-trophy'],
               ['Efisiensi thd HPS', rpS(ef), hps ? (ef / hps * 100).toLocaleString('id-ID', { maximumFractionDigits: 1 }) + '% dari HPS' : '-', '#E3343F', 'fa-arrow-trend-down']]
            .map(k => `<div class="col-6 col-xl-3"><div class="bk-kpi" style="--w:${k[3]}"><div class="d-flex justify-content-between"><div class="l">${k[0]}</div><i class="fas ${k[4]}"></i></div><div class="v">${k[1]}</div><div class="s">${k[2]}</div></div></div>`).join('')}
        </div>
        <div class="card shadow-sm p-3 mb-3">
            <div class="d-flex flex-wrap gap-2 align-items-center mb-2">
                <div class="d-flex flex-wrap gap-1">${chip('aktif', 'Aktif', akt.length)}${chip('PROSES', 'Proses', PBJ.data.filter(F.PROSES).length)}${chip('SIAP', 'Siap kontrak', PBJ.data.filter(F.SIAP).length)}${chip('KONTRAK', 'Kontrak', PBJ.data.filter(F.KONTRAK).length)}${chip('BATAL', 'Batal', PBJ.data.filter(F.BATAL).length)}</div>
                <input type="search" class="form-control form-control-sm ms-auto" style="max-width:260px" placeholder="Cari paket, bon, vendor, PO…" value="${e(PBJ.cari)}" id="pbjCari" oninput="PBJ.cari=this.value; window.__fokus='pbjCari'; renderPBJ()">
                ${entri ? `<button type="button" class="btn btn-sm btn-primary" onclick="pbjDariBon()"><i class="fas fa-clipboard-list me-1"></i>Paket baru dari Bon</button>
                <button type="button" class="btn btn-sm btn-outline-primary" onclick="pbjBaru()"><i class="fas fa-plus me-1"></i>Paket kosong</button>
                <button type="button" class="btn btn-sm btn-light border" onclick="pbjImpor()" title="Impor berkas JSON hasil Ekspor PBJ Studio lama"><i class="fas fa-file-import me-1"></i>Impor JSON PBJ Studio</button>
                <button type="button" class="btn btn-sm btn-outline-danger" onclick="histImpor()" title="Lengkapi riwayat tender yang sudah selesai (tanpa tender ulang) dan tautkan ke Bon & kontrak yang sudah ada"><i class="fas fa-clock-rotate-left me-1"></i>Impor PBJ historis</button>` : ''}
                <button type="button" class="btn btn-sm btn-light border" onclick="muatPBJ(true)" title="Muat ulang dari server"><i class="fas fa-rotate${PBJ.memuat ? ' fa-spin' : ''}"></i></button>
            </div>
            <div class="table-responsive"><table class="table table-sm table-hover align-middle mb-0 tbl-pbj">
                <thead class="table-light"><tr><th>Paket</th><th>Bon</th><th style="min-width:120px">Tahap</th><th>Pemenang</th><th class="text-end">HPS</th><th class="text-end">Final</th><th>SAP</th><th>Kontrak</th><th>Status</th><th></th></tr></thead>
                <tbody>${rows.length ? rows.map(p => { const kt = kandidatTaut(p); return `<tr>
                    <td><a href="#" class="fw-semibold" onclick="pbjBuka('${e(p.id)}'); return false;">${e(p.nama)}</a>${p.state && p.state.historis ? ' <span class="badge text-bg-dark border" title="Riwayat PBJ historis diimpor ' + e(String(p.state.historis.diimporPada || '').slice(0, 10)) + '"><i class="fas fa-clock-rotate-left me-1"></i>Historis</span>' : ''}<div class="small text-muted font-monospace">${e(p.kode)} · ${e((p.diubahPada || '').slice(0, 10))} · ${e(p.diubahOleh || '')}</div></td>
                    <td class="small">${[...new Set((p.bon || []).map(b => b.nomor))].map(n => `<span class="badge text-bg-light border font-monospace">${e(noBonPendek(n))}</span>`).join(' ') || '<span class="text-muted">—</span>'}${(p.bon || []).length ? `<div class="text-muted">${p.bon.length} item</div>` : ''}</td>
                    <td><div class="bk-prog"><div class="bar"><span style="width:${(N(p.tahap) / 12 * 100).toFixed(0)}%;background:${N(p.tahap) >= 12 ? '#2E9E5B' : '#1763B3'}"></span></div><b>${N(p.tahap)}/12</b></div></td>
                    <td class="small">${e(p.pemenang || '-')}</td>
                    <td class="text-end text-nowrap">${p.hps ? fmtRpSingkat(p.hps) : '-'}</td>
                    <td class="text-end text-nowrap">${p.final ? fmtRpSingkat(p.final) : '-'}${p.efisiensi > 0 ? `<div class="small text-success">−${fmtRpSingkat(p.efisiensi)}</div>` : ''}</td>
                    <td class="text-nowrap">${sapPills(p)}</td>
                    <td class="small">${p.noKontrak ? `<span class="font-monospace">${e(p.noKontrak.split('/').slice(0, 2).join('/'))}</span>` : kt && entri ? `<button class="btn btn-sm btn-outline-success py-0" onclick="pbjTautkan('${e(p.id)}','${e(kt.noKontrak)}')">Tautkan ${e(kt.noKontrak.split('/').slice(0, 2).join('/'))}</button>` : '<span class="text-muted">—</span>'}</td>
                    <td>${badgePBJ(p.status)}${p.status === 'BATAL' && p.alasanBatal ? `<div class="small text-muted text-truncate" style="max-width:140px" title="${e(p.alasanBatal)}">${e(p.alasanBatal)}</div>` : ''}</td>
                    <td class="text-nowrap text-end"><button class="btn btn-sm btn-light border py-0" onclick="pbjBuka('${e(p.id)}')" title="Buka"><i class="fas fa-folder-open"></i></button>
                        ${entri && p.status !== 'BATAL' && !p.noKontrak ? `<button class="btn btn-sm btn-light border py-0 text-danger" onclick="pbjBatal('${e(p.id)}')" title="Batalkan paket"><i class="fas fa-ban"></i></button>` : ''}
                        ${entri && adalahAdmin() && p.status === 'BATAL' ? `<button class="btn btn-sm btn-light border py-0" onclick="pbjPulihkan('${e(p.id)}')" title="Pulihkan (Admin)"><i class="fas fa-rotate-left"></i></button><button class="btn btn-sm btn-light border py-0 text-danger" onclick="pbjHapus('${e(p.id)}')" title="Hapus permanen (Admin)"><i class="fas fa-trash"></i></button>` : ''}</td>
                </tr>`; }).join('') : `<tr><td colspan="10" class="text-center text-muted py-4">${PBJ.memuat ? 'Memuat…' : PBJ.data.length ? 'Tidak ada paket pada filter ini.' : PBJ.dukung === false ? 'Fitur paket PBJ tersedia setelah server diperbarui ke v2.3.' : entri ? 'Belum ada paket PBJ. Mulai dari tombol <b>Paket baru dari Bon</b>.' : 'Belum ada paket PBJ.'}</td></tr>`}</tbody>
            </table></div>
        </div>
        <div class="card shadow-sm p-3">
            <div class="d-flex align-items-center mb-2"><h6 class="fw-bold mb-0"><i class="fas fa-inbox me-2"></i>Item Bon belum diproses PBJ / kontrak</h6><span class="badge text-bg-warning ms-2">${bonBelum.length}</span>
                ${entri && bonBelum.length ? '<button class="btn btn-sm btn-outline-primary ms-auto" onclick="pbjDariBon()">Proses jadi paket PBJ</button>' : ''}</div>
            ${bonBelum.length ? `<div class="table-responsive" style="max-height:280px"><table class="table table-sm mb-0"><thead class="table-light"><tr><th>Bon</th><th>Tgl</th><th>Dept</th><th>Item</th><th class="text-end">Vol</th><th class="text-end">Estimasi</th><th>WBS</th></tr></thead><tbody>
                ${bonBelum.slice(0, 200).map(x => `<tr><td class="font-monospace small">${e(noBonPendek(x.b.nomor))}</td><td class="small">${e(x.b.tanggal || '')}</td><td class="small">${e(x.b.departemen || '')}</td><td>${x.it.kode ? `<code>${e(x.it.kode)}</code> ` : ''}${e(x.it.uraian)}</td><td class="text-end">${fmtAngka(x.it.vol)} ${e(x.it.sat || '')}</td><td class="text-end">${x.it.harga ? fmtRpSingkat(N(x.it.vol) * N(x.it.harga)) : '-'}</td><td class="small font-monospace">${e(x.it.wbs || x.b.wbs || '-')}</td></tr>`).join('')}</tbody></table></div>` : '<div class="small text-muted">Semua item Bon sudah masuk paket PBJ atau kontrak.</div>'}
        </div>`;
        kembalikanFokus();
    }

    /* =================================================================
       6. PILIH ITEM BON (modal) — Bon → PBJ tanpa duplikasi
       ================================================================= */
    window.pastikanModal = pastikanModal;   // [2.1.9] dipakai modul lain (checklist)
    function pastikanModal(id, judul, lebar) {
        let m = document.getElementById(id); if (m) return m;
        m = document.createElement('div'); m.className = 'modal fade'; m.id = id; m.tabIndex = -1;
        m.innerHTML = `<div class="modal-dialog ${lebar || 'modal-xl'} modal-dialog-scrollable modal-fullscreen-md-down"><div class="modal-content">
            <div class="modal-header" style="background:#0B2B54;color:#fff;border-bottom:3px solid #E3343F"><h5 class="modal-title" id="${id}Judul">${judul}</h5><button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal" aria-label="Tutup"></button></div>
            <div class="modal-body" id="${id}Isi"></div><div class="modal-footer" id="${id}Kaki"></div></div></div>`;
        document.body.appendChild(m); return m;
    }
    const BP = { pilih: new Set(), cari: '', mode: 'baru', cb: null, kecuali: null, dipakaiEditor: new Set() };
    function bukaPilihBon(mode, cb) {
        BP.pilih = new Set(); BP.cari = ''; BP.mode = mode; BP.cb = cb;
        BP.kecuali = mode === 'tambah' && PBJ.ed ? PBJ.ed.id : null;
        BP.dipakaiEditor = new Set();
        if (mode === 'tambah') { try { pbjFrameApi().bonDipakai().forEach(b => BP.dipakaiEditor.add(b.nomor + '#' + b.idx)); } catch (err) { } }
        pastikanModal('modalPilihBon', '<i class="fas fa-clipboard-list me-2"></i>Pilih item Bon Permintaan');
        renderPilihBon(); tampilModal('modalPilihBon', true);
    }
    function renderPilihBon() {
        const alok = alokasiBon(BP.kecuali), q = BP.cari.trim().toLowerCase();
        const bons = (PMT.data || []).slice().sort((a, b) => String(b.tanggal).localeCompare(String(a.tanggal)))
            .filter(b => !q || [b.nomor, b.departemen, b.peminta, b.keperluan, ...(b.items || []).map(i => i.kode + ' ' + i.uraian)].join(' ').toLowerCase().includes(q));
        const isi = document.getElementById('modalPilihBonIsi');
        isi.innerHTML = `<div class="d-flex flex-wrap gap-2 mb-2 align-items-center"><input type="search" class="form-control form-control-sm" style="max-width:320px" placeholder="Cari nomor bon, item, peminta…" value="${e(BP.cari)}" oninput="BP_cari(this)">
            <span class="small text-muted ms-auto">Item yang sudah dipakai paket lain / sudah dikontrakkan tidak dapat dipilih (mencegah duplikasi).</span></div>
            ${bons.length ? bons.slice(0, 120).map(b => { const st = statusKontrakPermintaan(b); return `<div class="border rounded p-2 mb-2">
                <div class="d-flex flex-wrap gap-2 align-items-center mb-1"><span class="font-monospace fw-bold">${e(b.nomor)}</span><span class="small text-muted">${e(b.tanggal || '')} · ${e(b.departemen || '')} · ${e(b.peminta || '')}${b.keperluan ? ' · ' + e(b.keperluan) : ''}</span>
                <button type="button" class="btn btn-sm btn-link ms-auto py-0" onclick="BP_semua('${e(b.nomor)}')">pilih semua yang tersedia</button></div>
                ${(b.items || []).map((it, i) => { const k = b.nomor + '#' + i, pk = alok.get(k), ed = BP.dipakaiEditor.has(k), kon = st.sudah[i];
                    const off = !!(pk || ed || kon), ket = ed ? '<span class="badge text-bg-info">sudah di paket ini</span>' : pk ? `<span class="badge text-bg-secondary">dipakai ${e(pk.kode)}</span>` : kon ? '<span class="badge text-bg-success">sudah dikontrakkan</span>' : '';
                    return `<label class="d-flex gap-2 align-items-start py-1 border-top small ${off ? 'opacity-50' : ''}"><input type="checkbox" class="form-check-input mt-1" ${off ? 'disabled' : ''} ${BP.pilih.has(k) ? 'checked' : ''} onchange="BP_toggle('${e(k)}', this.checked)">
                        <span class="flex-grow-1">${it.kode ? `<code>${e(it.kode)}</code> ` : ''}${e(it.uraian)} · <b>${fmtAngka(it.vol)} ${e(it.sat || '')}</b>${it.harga ? ' · est. ' + fmtRp(it.harga) + '/' + e(it.sat || 'sat') : ''}${(it.wbs || b.wbs) ? ` · WBS <span class="font-monospace">${e(it.wbs || b.wbs)}</span>` : ''}</span>${ket}</label>`; }).join('')}
            </div>`; }).join('') : '<div class="text-muted small py-3 text-center">Belum ada Bon Permintaan. Buat dulu di menu Bon Permintaan.</div>'}`;
        document.getElementById('modalPilihBonKaki').innerHTML = `<span class="me-auto small"><b id="bpJumlah">${BP.pilih.size}</b> item dipilih</span>
            <button type="button" class="btn btn-light border" data-bs-dismiss="modal">Batal</button>
            <button type="button" class="btn btn-primary" onclick="BP_ok()" ${BP.pilih.size ? '' : 'disabled'} id="bpOk"><i class="fas fa-check me-1"></i>${BP.mode === 'tambah' ? 'Tambahkan ke paket' : 'Buat paket PBJ'}</button>`;
    }
    window.BP_cari = el => { BP.cari = el.value; renderPilihBon(); const i = document.querySelector('#modalPilihBonIsi input[type=search]'); if (i) { i.focus(); i.setSelectionRange(i.value.length, i.value.length); } };
    window.BP_toggle = (k, v) => { v ? BP.pilih.add(k) : BP.pilih.delete(k); const j = document.getElementById('bpJumlah'); if (j) j.textContent = BP.pilih.size; const b = document.getElementById('bpOk'); if (b) b.disabled = !BP.pilih.size; };
    window.BP_semua = nomor => {
        const b = PMT.data.find(x => x.nomor === nomor); if (!b) return; const alok = alokasiBon(BP.kecuali), st = statusKontrakPermintaan(b);
        (b.items || []).forEach((it, i) => { const k = nomor + '#' + i; if (!alok.has(k) && !BP.dipakaiEditor.has(k) && !st.sudah[i]) BP.pilih.add(k); });
        renderPilihBon();
    };
    window.BP_ok = () => {
        const list = [...BP.pilih].map(k => { const j = k.lastIndexOf('#'), nomor = k.slice(0, j), idx = Number(k.slice(j + 1)), b = PMT.data.find(x => x.nomor === nomor), it = b && b.items[idx];
            return it ? { nomor, idx, kode: it.kode || '', uraian: it.uraian || '', vol: N(it.vol), sat: it.sat || '', harga: N(it.harga), wbs: it.wbs || b.wbs || '' } : null; }).filter(Boolean);
        tampilModal('modalPilihBon', false);
        if (BP.cb) BP.cb(list);
    };

    /* =================================================================
       7. EDITOR PAKET — PBJ Studio di dalam bingkai (iframe), tersimpan ke server
       ================================================================= */
    const PBJ_HTML = "<!doctype html>\n<html lang=\"id\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n</head>\n<body>\n<title>PBJ Studio · Monitoring Pengadaan</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&family=Arimo:ital,wght@0,400;0,700;1,400&display=swap\">\n<style>\n/* Layout: header bar di atas, sidebar tahapan di kiri, area kerja form | pratinjau A4 di kanan. Dark-first, satu tema (dasbor engineering). */\n:root{\n  --bg:#0e1215; --panel:#151a1f; --panel2:#1b2228; --line:#28313a; --line2:#34404b;\n  --fg:#e4e8eb; --muted:#8b97a2; --dim:#5f6b76;\n  --accent:#f2c230; --accent-ink:#1a1503;\n  --ok:#3fbf7f; --bad:#ec5b52; --warn:#f0a03e;\n  --s1:#5aa9e6; --s2:#e58f6a; --s3:#b48ef0;\n  --f-disp:\"Barlow Condensed\",\"Arial Narrow\",sans-serif;\n  --f-body:\"IBM Plex Sans\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --f-mono:\"IBM Plex Mono\",ui-monospace,Menlo,Consolas,monospace;\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\nhtml,body{height:100%}\nbody{background:var(--bg);color:var(--fg);font:14px/1.5 var(--f-body);margin:0}\nbutton,input,select,textarea{font:inherit;color:inherit}\n:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.num,.mono{font-family:var(--f-mono);font-variant-numeric:tabular-nums}\n\n/* ---------- shell ---------- */\n.app{display:grid;grid-template-columns:248px minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);height:100%}\nheader.top{grid-column:1/-1;display:flex;flex-wrap:wrap;align-items:center;gap:10px 18px;padding:10px 18px;border-bottom:1px solid var(--line);background:var(--panel);position:sticky;top:env(safe-area-inset-top,0px);z-index:5}\n.brand{display:flex;flex-direction:column;min-width:0;flex:1 1 320px}\n.brand .eyebrow{font:600 11px/1 var(--f-disp);letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}\n.brand h1{margin:3px 0 0;font:600 20px/1.15 var(--f-disp);letter-spacing:.01em;text-wrap:balance}\n.brand .sub{color:var(--muted);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{display:flex;flex-direction:column;padding:4px 10px;border:1px solid var(--line2);border-radius:4px;background:var(--panel2);min-width:0}\n.chip b{font:500 10px/1.2 var(--f-disp);letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.chip span{font:500 13px/1.3 var(--f-mono)}\n.chip.good span{color:var(--ok)}\n.actions{display:flex;gap:8px;flex-wrap:wrap}\n.btn{border:1px solid var(--line2);background:var(--panel2);padding:7px 12px;border-radius:4px;cursor:pointer;font-weight:500;font-size:13px;display:inline-flex;align-items:center;gap:6px;white-space:nowrap}\n.btn:hover{border-color:var(--muted)}\n.btn.pri{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}\n.btn.pri:hover{filter:brightness(1.08)}\n.btn.sm{padding:4px 9px;font-size:12px}\n.btn.danger{color:var(--bad)}\n.btn:disabled{opacity:.45;cursor:not-allowed}\n\nnav.side{border-right:1px solid var(--line);background:var(--panel);overflow:auto;display:flex;flex-direction:column;padding:12px 0}\n.navgrp{font:600 11px/1 var(--f-disp);letter-spacing:.14em;text-transform:uppercase;color:var(--dim);padding:12px 18px 6px}\n.nav a{display:flex;align-items:center;gap:10px;padding:7px 18px;color:var(--fg);text-decoration:none;font-size:13px;border-left:3px solid transparent;cursor:pointer}\n.nav a:hover{background:var(--panel2)}\n.nav a.on{background:rgba(242,194,48,.10);border-left-color:var(--accent);color:var(--accent)}\n.nav .n{font:500 12px var(--f-mono);color:var(--muted);width:20px;text-align:right}\n.nav a.on .n{color:var(--accent)}\n.dot{width:8px;height:8px;border-radius:50%;flex:none;background:var(--bad)}\n.dot.ok{background:var(--ok)}\n.nav .lbl{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.side-foot{margin-top:auto;padding:14px 18px 6px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}\n.side-foot b{color:var(--fg);font-family:var(--f-mono)}\n.meter{height:6px;background:var(--line);border-radius:3px;margin-top:8px;overflow:hidden}\n.meter i{display:block;height:100%;background:var(--ok)}\n\nmain{overflow:auto;min-width:0;padding-block:18px 40px;padding-inline:20px}\n.pagehead{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:10px;margin-bottom:14px}\n.pagehead h2{margin:0;font:600 26px/1.1 var(--f-disp);text-wrap:balance}\n.pagehead .k{font:600 11px/1 var(--f-disp);letter-spacing:.14em;text-transform:uppercase;color:var(--accent);margin-bottom:4px}\n.pagehead p{margin:4px 0 0;color:var(--muted);font-size:13px;max-width:70ch}\n\n/* ---------- panels & forms ---------- */\n.work{display:grid;grid-template-columns:minmax(0,440px) minmax(0,1fr);gap:18px;align-items:start}\n.panel{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:14px 16px;min-width:0}\n.panel+.panel{margin-top:14px}\n.panel h3{margin:0 0 10px;font:600 15px/1.2 var(--f-disp);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);display:flex;justify-content:space-between;align-items:center;gap:8px}\n.fg{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 12px}\n.fg .full{grid-column:1/-1}\nlabel.f{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted);min-width:0}\nlabel.f input,label.f select,label.f textarea,.cell input,.cell select{background:var(--bg);border:1px solid var(--line2);border-radius:4px;padding:6px 8px;font-size:13px;color:var(--fg);width:100%;min-width:0}\nlabel.f textarea{min-height:64px;resize:vertical}\ninput[type=number]{font-family:var(--f-mono)}\n.tbl-wrap{overflow-x:a