;i++){if(a[ks[i]]==null)a[ks[i]]={};a=a[ks[i]]}a[ks[ks.length-1]]=v}\n\n/* =========================================================\n   UTILITAS FORMAT\n   ========================================================= */\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst N=v=>{const n=Number(v);return isFinite(n)?n:0};\nconst fmt=n=>Math.round(N(n)).toLocaleString('id-ID');\nconst fmtD=(n,d=2)=>N(n).toLocaleString('id-ID',{minimumFractionDigits:d,maximumFractionDigits:d});\nconst rp=n=>'Rp '+fmt(n);\nconst pct=(n,d=2)=>fmtD(n*100,d)+'%';\nfunction pDate(iso){if(!iso)return null;const m=/^(\\d{4})-(\\d{2})-(\\d{2})/.exec(iso);return m?new Date(+m[1],+m[2]-1,+m[3]):null}\nfunction tglID(iso){const d=pDate(iso);return d?`${d.getDate()} ${BULAN[d.getMonth()]} ${d.getFullYear()}`:'……………'}\nfunction hariID(iso){const d=pDate(iso);return d?HARI[d.getDay()]:'……'}\nfunction hariTgl(iso){return pDate(iso)?`${hariID(iso)}, ${tglID(iso)}`:'……………'}\nfunction addDays(iso,n){const d=pDate(iso);if(!d)return '';d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}\nfunction tglKalimat(iso){const d=pDate(iso);if(!d)return '……………';const dd=String(d.getDate()).padStart(2,'0'),mm=String(d.getMonth()+1).padStart(2,'0');return `${HARI[d.getDay()]} tanggal ${tb(d.getDate())} bulan ${BULAN[d.getMonth()]} tahun ${tb(d.getFullYear())} (${dd} - ${mm} - ${d.getFullYear()})`}\nfunction tb(n){\n  const s=['','Satu','Dua','Tiga','Empat','Lima','Enam','Tujuh','Delapan','Sembilan','Sepuluh','Sebelas'];\n  n=Math.floor(Math.abs(n));\n  const j=(a,b)=>b?a+' '+b:a;\n  if(n<12)return s[n];\n  if(n<20)return tb(n-10)+' Belas';\n  if(n<100)return j(tb(Math.floor(n/10))+' Puluh',tb(n%10));\n  if(n<200)return j('Seratus',tb(n-100));\n  if(n<1000)return j(tb(Math.floor(n/100))+' Ratus',tb(n%100));\n  if(n<2000)return j('Seribu',tb(n-1000));\n  if(n<1e6)return j(tb(Math.floor(n/1000))+' Ribu',tb(n%1000));\n  if(n<1e9)return j(tb(Math.floor(n/1e6))+' Juta',tb(n%1e6));\n  if(n<1e12)return j(tb(Math.floor(n/1e9))+' Miliar',tb(n%1e9));\n  if(n<1e15)return j(tb(Math.floor(n/1e12))+' Triliun',tb(n%1e12));\n  return 'Melebihi batas terbilang (≥ 1.000 Triliun)';\n}\nfunction terbilang(n){n=Math.round(N(n));if(n===0)return 'Nol Rupiah';return (n<0?'Minus ':'')+tb(n)+' Rupiah'}\nfunction romawi(iso){const d=pDate(iso);return d?ROMAWI[d.getMonth()]:'…'}\nfunction tahun(iso){const d=pDate(iso);return d?d.getFullYear():'…'}\n\n/* =========================================================\n   PERHITUNGAN\n   ========================================================= */\nfunction compute(){\n  const C={};\n  const byName={};S.vendors.forEach(v=>{const key=v.nama.trim().toLowerCase();if(key&&!byName[key])byName[key]=v});\n  C.vByName=n=>byName[String(n||'').trim().toLowerCase()]||null;\n  C.vById=id=>S.vendors.find(v=>v.id===id)||null;\n  C.hps=S.items.reduce((a,it)=>a+N(it.vol)*N(it.hps),0);\n  C.tot={};S.vendors.forEach(v=>{let a=0,f=0;S.items.forEach(it=>{a+=N(it.vol)*N(it.awal?.[v.id]);f+=N(it.vol)*N(it.final?.[v.id])});C.tot[v.id]={awal:a,final:f}});\n  // status pembanding\n  const names=S.pemb.map(x=>String(x||'').trim().toLowerCase());\n  C.pemb=S.pemb.map((nm,i)=>{\n    const name=String(nm||'').trim();let st='OK',cls='ok',v=null;\n    if(!name){st='Belum dipilih';cls='warn'}\n    else if(!(v=C.vByName(name))){st='Tidak ada di DB';cls='bad'}\n    else if(names.filter(x=>x===name.toLowerCase()).length>1){st='Duplikat';cls='bad'}\n    return {pos:i,name,v,st,cls,ok:st==='OK',awal:v?C.tot[v.id].awal:0,final:v?C.tot[v.id].final:0};\n  });\n  const okP=C.pemb.filter(p=>p.ok&&p.final>0);\n  C.pemb.forEach(p=>{p.rank=(p.ok&&p.final>0)?1+okP.filter(q=>q.final<p.final).length:null});\n  C.rek=okP.length?okP.slice().sort((a,b)=>a.final-b.final)[0]:null;\n  // skor\n  C.bobotTot=S.bobot.reduce((a,b)=>a+N(b),0);\n  C.nilaiOf=(vid,i)=>{if(KRIT[i].auto){const f=C.tot[vid]?.final||0;return f>0?Math.min(1,C.hps/f):0}const arr=S.nilai[vid];return arr?N(arr[i]):0};\n  C.skorOf=vid=>KRIT.reduce((a,k,i)=>a+N(S.bobot[i])*C.nilaiOf(vid,i),0);\n  C.pemb.forEach(p=>{p.skor=p.v?C.skorOf(p.v.id):0});\n  const sk=C.pemb.filter(p=>p.ok);\n  C.pemb.forEach(p=>{p.rankSkor=p.ok?1+sk.filter(q=>q.skor>p.skor+1e-9).length:null});\n  C.topSkor=sk.length?sk.slice().sort((a,b)=>b.skor-a.skor)[0]:null;\n  // pemenang\n  const wn=String(S.pemenang||'').trim();\n  C.win={name:wn,v:C.vByName(wn),st:'OK',cls:'ok'};\n  if(!wn){C.win.st='Belum dipilih';C.win.cls='warn'}\n  else if(!C.win.v){C.win.st='Tidak ada di DB';C.win.cls='bad'}\n  else if(!C.pemb.some(p=>p.ok&&p.v&&p.v.id===C.win.v.id)){C.win.st='Bukan pembanding';C.win.cls='bad'}\n  C.win.ok=C.win.st==='OK';\n  C.final=C.win.ok?C.tot[C.win.v.id].final:0;\n  C.awalWin=C.win.ok?C.tot[C.win.v.id].awal:0;\n  C.ppn=Math.round(C.final*N(S.paket.ppn));\n  C.finalPpn=C.final+C.ppn;\n  C.efis=C.hps-C.final;\n  C.efisPct=C.hps?C.efis/C.hps:0;\n  C.hpsPpn=Math.round(C.hps*(1+N(S.paket.ppn)));\n  C.siap=C.pemb.every(p=>p.ok)&&C.win.ok;\n  // peringatan\n  const W=[];\n  C.pemb.forEach(p=>{if(!p.ok)W.push(['bad',`Pembanding ${p.pos+1}: ${p.st}${p.name?' ('+p.name+')':''}.`])});\n  if(!C.win.ok)W.push(['bad',`Pemenang: ${C.win.st}. Pemenang harus salah satu dari 3 pembanding.`]);\n  C.pemb.filter(p=>p.ok).forEach(p=>{\n    if(p.final>C.hps&&C.hps>0)W.push(['warn',`Harga final ${p.name} (${rp(p.final)}) melebihi HPS (${rp(C.hps)}).`]);\n    if(p.final>p.awal)W.push(['warn',`Harga final ${p.name} lebih tinggi dari penawaran awal.`]);\n    S.items.forEach((it,ix)=>{const a=N(it.awal?.[p.v.id]),f=N(it.final?.[p.v.id]);if(f>a&&a>0&&S.items.length>1)W.push(['warn',`Item ${ix+1} (${it.uraian}): harsat final ${p.name} > harsat awal.`])});\n    if(p.final<=0)W.push(['bad',`Harga final ${p.name} belum diisi.`]);\n  });\n  if(C.rek&&C.win.ok&&C.rek.v.id!==C.win.v.id)W.push(['warn',`Pemenang terpilih berbeda dengan rekomendasi sistem (harga final terendah: ${C.rek.name}).`]);\n  if(C.rek&&C.topSkor&&C.rek.v.id!==C.topSkor.v.id)W.push(['warn',`Rekomendasi harga terendah (${C.rek.name}) berbeda dengan skor PB-01.2 tertinggi (${C.topSkor.name}, ${fmtD(C.topSkor.skor)}).`]);\n  if(Math.abs(C.bobotTot-100)>1e-9)W.push(['bad',`Total bobot PB-01.2 = ${fmtD(C.bobotTot)}; harus 100.`]);\n  KRIT.forEach((k,i)=>{if(k.auto)return;C.pemb.filter(p=>p.ok).forEach(p=>{const x=N(S.nilai[p.v.id]?.[i]);if(x<0||x>1)W.push(['bad',`Nilai \"${k.label}\" untuk ${p.name} harus 0–1.`])})});\n  C.warn=W;\n  // status tahapan\n  const dk=S.dok, has=(i,...f)=>f.every(x=>String(dk[i]?.[x]??'').trim()!=='');\n  const P=S.paket,T=S.tim;\n  const allPembFinal=C.pemb.every(p=>p.ok&&S.items.every(it=>N(it.awal?.[p.v.id])>0&&N(it.final?.[p.v.id])>0));\n  const nilaiOK=C.pemb.every(p=>p.ok&&KRIT.every((k,i)=>k.auto||(()=>{const x=S.nilai[p.v.id]?.[i];return x!==''&&x!=null&&N(x)>=0&&N(x)<=1})()));\n  C.stage=[\n    !!(P.nama&&P.proyek&&P.idProyek&&P.lokasi&&T.ketua&&T.penetap&&dk.every((d,i)=>d.tgl&&(!DOKS[i].numbered||String(d.no||'').trim()&&d.no!=='-'))),\n    C.pemb.every(p=>p.ok),\n    S.items.length>0&&C.hps>0&&S.items.every(it=>it.uraian&&N(it.vol)>0&&N(it.hps)>0)&&allPembFinal,\n    has(0,'no','tgl')&&!!P.nama,\n    has(1,'no','tgl','acara','jam','tempat'),\n    has(2,'tgl')&&S.aan.sel.every(a=>a.length>0),\n    has(3,'no','tgl','acara')&&S.vendors.length>0,\n    has(4,'no','tgl','acara','jam','tempat')&&has(5,'tgl')&&allPembFinal,\n    has(6,'tgl')&&allPembFinal&&C.hps>0,\n    has(7,'tgl')&&Math.abs(C.bobotTot-100)<1e-9&&nilaiOK,\n    has(8,'no','tgl')&&has(9,'no','tgl')&&C.win.ok,\n    has(10,'no','tgl')&&has(11,'no','tgl')&&C.siap\n  ];\n  C.stageOk=C.stage.filter(Boolean).length;\n  return C;\n}\nlet C=compute();\n\n/* =========================================================\n   DOKUMEN — bagian umum\n   ========================================================= */\nconst P=()=>S.paket, T=()=>S.tim;\nfunction kop(){return `<div class=\"kop\"><div><div class=\"co\">${esc(P().perusahaan)}</div><div class=\"ksub\">${esc(P().unit)}</div></div><div class=\"kr\">${esc(P().proyek)}<br>ID Proyek ${esc(P().idProyek)}</div></div>`}\nfunction formHead(title,code){return `${kop()}<div class=\"formhead\"><div class=\"fl\"><table class=\"meta\"><tr><td class=\"k\">Business Unit</td><td class=\"c\">:</td><td>${esc(P().unit)}</td></tr><tr><td class=\"k\">Proyek &amp; ID Proyek</td><td class=\"c\">:</td><td>${esc(P().proyek)} / ${esc(P().idProyek)}</td></tr></table></div><div class=\"fr\">${code}</div></div><h1>${esc(title)}</h1>`}\nfunction stamp(){return C.siap?'':'<div class=\"stamp\">DRAF – BELUM SIAP CETAK</div>'}\nfunction paper(inner,land){return `<div class=\"paper${land?' land':''}\">${stamp()}${inner}</div>`}\nfunction letterMeta(no,tgl){return `<table class=\"meta\" style=\"width:auto;margin-bottom:8pt\"><tr><td class=\"k\">Nomor</td><td class=\"c\">:</td><td>${esc(no)}</td></tr><tr><td class=\"k\">Tanggal</td><td class=\"c\">:</td><td>${tglID(tgl)}</td></tr></table>`}\nfunction kepada(lines){return `<p style=\"margin-bottom:8pt;text-align:left\">Kepada Yth.<br>${lines.filter(Boolean).map(esc).join('<br>')}<br>di –<br><span style=\"padding-left:14pt\">Tempat</span></p>`}\nfunction perihal(t){return `<table class=\"meta\" style=\"margin-bottom:9pt\"><tr><td class=\"k\">Perihal</td><td class=\"c\">:</td><td class=\"b\">${t}</td></tr></table>`}\nfunction sigKetua(withCo){return `<div class=\"letter-sig\">Hormat kami,<br>${withCo?esc(P().perusahaan)+'<br>':''}Ketua Tim Pengadaan<div class=\"sp\"></div><div class=\"nm\">${esc(T().ketua)}</div>${esc(T().jabKetua)}</div>`}\nfunction tembusan(extra){const t=[P().tembusan,'Arsip'].filter(Boolean);if(extra===false)t.shift();return `<div class=\"foot\">Lampiran : ${extra&&extra.lamp?esc(extra.lamp):'-'}<br>Tembusan :<ol style=\"margin:0\">${t.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div>`}\nfunction vendorTo(v){return v?[v.jabatan||'Direktur',v.nama,v.alamat,v.pimpinan?'Up. Bapak/Ibu '+v.pimpinan:'']:['Direktur','Para Calon Rekanan Waskita']}\nfunction teamSig(){\n  const t=T();return `<div class=\"sig\" style=\"grid-template-columns:1fr 1fr 1.3fr\"><div class=\"s\">Diverifikasi:<br>Ketua Tim Pengadaan<div class=\"sp\"></div><span class=\"nm\">${esc(t.ketua)}</span></div><div class=\"s\">Dibuat:<br>Sekretaris Tim Pengadaan<div class=\"sp\"></div><span class=\"nm\">${esc(t.sekretaris)}</span></div><div class=\"s\" style=\"text-align:left\">Anggota Tim Pengadaan (paraf):<table class=\"g sm\" style=\"margin-top:4pt\">${t.anggota.filter(Boolean).map((a,i)=>`<tr><td style=\"width:14pt\">${i+1}.</td><td>${esc(a)}</td><td style=\"width:44pt\"></td></tr>`).join('')}</table></div></div>`;\n}\nfunction itemTable(vid,mode){\n  // mode: 'hps' | 'rfq'\n  let rows=S.items.map((it,i)=>`<tr><td class=\"c\">${i+1}</td><td>${esc(it.uraian)}</td><td>${esc(it.spek)}</td><td class=\"c\">${esc(it.satuan)}</td><td class=\"r\">${fmt(it.vol)}</td>${mode==='hps'?`<td class=\"r\">${fmt(it.hps)}</td><td class=\"r\">${fmt(N(it.vol)*N(it.hps))}</td>`:''}</tr>`).join('');\n  return `<table class=\"g\"><tr><th>No</th><th>Uraian</th><th>Spesifikasi Teknis</th><th>Sat.</th><th>Volume</th>${mode==='hps'?'<th>Harsat HPS (Rp)</th><th>Jumlah (Rp)</th>':''}</tr>${rows}${mode==='hps'?`<tr class=\"tot\"><td colspan=\"6\" class=\"r\">JUMLAH (belum PPN)</td><td class=\"r\">${fmt(C.hps)}</td></tr>`:''}</table>`;\n}\nfunction vendorsFor(sel){if(sel==='all')return [null];const v=C.vById(sel);return [v]}\nfunction pembVendors(){return C.pemb.filter(p=>p.ok).map(p=>p.v)}\n\n/* =========================================================\n   DOKUMEN — per tahap\n   ========================================================= */\nfunction docParam(){\n  const p=P(),t=T();\n  const rows=[['Nama Perusahaan',p.perusahaan],['Nama Paket',p.nama],['Deskripsi',p.deskripsi],['Material/Alat/Pekerjaan',p.material],['Proyek',p.proyek],['ID Proyek',p.idProyek],['Business Unit',p.unit],['Lokasi / Franco',p.lokasi],['Jangka Waktu',p.waktu],['Jenis Kontrak',p.jenisKontrak],['Jenis Pekerjaan',p.jenisPek],['Pengakuan Progress',p.progress],['Uang Muka',p.um],['Cara Pembayaran',p.bayar],['Metode Pengadaan',p.metode],['Sumber Dana',p.dana],['HPS (belum PPN)',rp(C.hps)],['Tarif PPN',pct(N(p.ppn),0)]];\n  const team=[['Ketua',t.ketua+' — '+t.jabKetua],['Sekretaris',t.sekretaris],...t.anggota.map((a,i)=>['Anggota '+(i+1),a]),['Pejabat Penetap',t.penetap+' — '+t.jabPenetap1+' '+t.jabPenetap2]];\n  return paper(`${kop()}<h1>LEMBAR PARAMETER PENGADAAN</h1><p class=\"ctr sm\" style=\"margin-bottom:8pt\">${esc(p.nama)}</p>\n  <table class=\"g sm\"><tr><th colspan=\"2\">A. Parameter Paket &amp; Proyek</th></tr>${rows.map(r=>`<tr><td style=\"width:36%\">${esc(r[0])}</td><td>${esc(r[1])}</td></tr>`).join('')}</table>\n  <table class=\"g sm\"><tr><th colspan=\"2\">B. Tim Pengadaan</th></tr>${team.map(r=>`<tr><td style=\"width:36%\">${esc(r[0])}</td><td>${esc(r[1])}</td></tr>`).join('')}</table>\n  <table class=\"g sm\"><tr><th>No</th><th>Dokumen</th><th>Nomor</th><th>Tanggal</th><th>Acara / Batas</th></tr>${S.dok.map((d,i)=>`<tr><td class=\"c\">${i+1}</td><td>${esc(DOKS[i].nama)}</td><td>${esc(d.no||'-')}</td><td>${tglID(d.tgl)}</td><td>${d.acara?tglID(d.acara)+(d.jam?', '+esc(d.jam):''):'-'}</td></tr>`).join('')}</table>`);\n}\nfunction docVendor(){\n  const rows=S.vendors.map((v,i)=>{const p=C.pemb.find(x=>x.v&&x.v.id===v.id&&x.ok);return `<tr><td class=\"c\">${i+1}</td><td>${esc(v.nama)}${p?` <span class=\"tag\">P${p.pos+1}</span>`:''}</td><td>${esc(v.alamat)}</td><td>${esc(v.pimpinan)}</td><td>${esc(v.npwp)}</td><td>${esc(v.kualifikasi)}</td><td>${esc(v.wave)}</td></tr>`}).join('');\n  const pb=C.pemb.map(p=>`<tr><td>Pembanding ${p.pos+1}</td><td>${esc(p.name||'—')}</td><td class=\"c\">${esc(p.st)}</td><td class=\"r\">${p.final?fmt(p.final):'-'}</td><td class=\"c\">${p.rank??'-'}</td></tr>`).join('');\n  return paper(`${kop()}<h1>DAFTAR CALON PENYEDIA &amp; VENDOR PEMBANDING</h1><p class=\"ctr sm\">${esc(P().nama)}</p>\n  <table class=\"g xs\"><tr><th>No</th><th>Nama Perusahaan</th><th>Alamat</th><th>Pimpinan</th><th>NPWP</th><th>Kualifikasi</th><th>Status WAVE</th></tr>${rows}</table>\n  <table class=\"g sm\"><tr><th>Posisi</th><th>Vendor</th><th>Status</th><th>Total Final (Rp)</th><th>Peringkat</th></tr>${pb}</table>\n  <p class=\"sm\">Rekomendasi sistem (harga final terendah): <b>${esc(C.rek?C.rek.name:'-')}</b></p>${teamSig()}`);\n}\nfunction docHPS(){\n  const vs=S.vendors;\n  const rows=vs.map((v,i)=>{const t=C.tot[v.id];const d=t.awal?(t.awal-t.final)/t.awal:0;return `<tr><td class=\"c\">${i+1}</td><td>${esc(v.nama)}</td><td class=\"r\">${fmt(t.awal)}</td><td class=\"r\">${fmt(t.final)}</td><td class=\"r\">${pct(d)}</td><td class=\"r\">${C.hps?pct(t.final/C.hps):'-'}</td></tr>`}).join('');\n  return paper(`${kop()}<h1>RINCIAN ITEM, HPS &amp; REKAP PENAWARAN</h1><p class=\"ctr sm\">${esc(P().nama)}</p>${itemTable(null,'hps')}\n  <table class=\"g sm\"><tr><th>No</th><th>Vendor</th><th>Penawaran Awal (Rp)</th><th>Penawaran Final (Rp)</th><th>% Turun Nego</th><th>Final / HPS</th></tr>${rows}</table><p class=\"xs\">Seluruh harga belum termasuk PPN ${pct(N(P().ppn),0)}.</p>`);\n}\nfunction docUndangan(v){\n  const p=P(),d=S.dok[0];\n  return paper(`${kop()}${letterMeta(d.no,d.tgl)}${kepada(vendorTo(v))}${perihal(`Undangan Mengikuti ${esc(p.metode)} ${esc(p.nama)}<br>${esc(p.proyek)}`)}\n  <p>Dengan hormat,</p><p>Sehubungan dengan rencana ${esc(p.metode)} ${esc(p.nama)} pada ${esc(p.proyek)} ${esc(p.perusahaan)}, dengan ini kami mengundang ${v?'Bapak/Ibu':'para calon rekanan'} untuk mengikuti ${esc(p.metode.toLowerCase())} dengan rincian sebagai berikut:</p>\n  <table class=\"g\"><tr><th style=\"width:24pt\">No</th><th style=\"width:38%\">Uraian</th><th>Penjelasan</th></tr>\n  <tr><td class=\"c\">1</td><td>Nama Pengadaan</td><td>${esc(p.nama)}</td></tr><tr><td class=\"c\">2</td><td>Lokasi Proyek</td><td>${esc(p.lokasi)}</td></tr><tr><td class=\"c\">3</td><td>Jangka Waktu Pelaksanaan</td><td>${esc(p.waktu)}</td></tr><tr><td class=\"c\">4</td><td>Deskripsi Pengadaan</td><td>${esc(p.deskripsi)}</td></tr><tr><td class=\"c\">5</td><td>Jenis Pekerjaan</td><td>${esc(p.jenisPek)}</td></tr><tr><td class=\"c\">6</td><td>Kondisi Penawaran:<br>a. Jenis Kontrak<br>b. Pengakuan Progress<br>c. Uang Muka<br>d. Cara Pembayaran</td><td><br>a. ${esc(p.jenisKontrak)}<br>b. ${esc(p.progress)}<br>c. ${esc(p.um)}<br>d. ${esc(p.bayar)}</td></tr></table>\n  <p>Terlampir Dokumen Tender (Spesifikasi Teknis dan Persyaratan lainnya) untuk dijadikan pedoman dalam ${esc(p.nama)}. Informasi mengenai Rapat Penjelasan Dokumen Pengadaan (Aanwijzing) akan disampaikan lebih lanjut.</p><p>Demikian kami sampaikan, atas perhatian dan kerja samanya kami ucapkan terima kasih.</p>\n  ${sigKetua()}${tembusan({lamp:'Dokumen Tender'})}`);\n}\nfunction docUndAan(v){\n  const p=P(),d=S.dok[1];\n  return paper(`${kop()}${letterMeta(d.no,d.tgl)}${kepada(vendorTo(v))}${perihal(`Undangan Penjelasan Pengadaan (Aanwijzing)<br>${esc(p.metode)} ${esc(p.nama)} ${esc(p.proyek)}`)}\n  <p>Dengan hormat,</p><p>Sehubungan dengan adanya ${esc(p.metode)} ${esc(p.nama)} ${esc(p.proyek)} di ${esc(p.perusahaan)}, bersama ini kami bermaksud mengundang Bapak/Ibu Rekanan dalam Rapat Penjelasan Pengadaan (Aanwijzing) yang akan dilaksanakan pada:</p>\n  <table class=\"meta\" style=\"margin:0 0 9pt 18pt;width:auto\"><tr><td class=\"k\">Hari/Tanggal</td><td class=\"c\">:</td><td>${hariTgl(d.acara)}</td></tr><tr><td class=\"k\">Waktu</td><td class=\"c\">:</td><td>Pukul ${esc(d.jam||'……')}</td></tr><tr><td class=\"k\">Tempat</td><td class=\"c\">:</td><td>${esc(d.tempat||'……')}</td></tr><tr><td class=\"k\">Agenda</td><td class=\"c\">:</td><td>Penjelasan lingkup, spesifikasi teknis, syarat komersial dan jadwal pengadaan</td></tr></table>\n  <p>Mengingat pentingnya rapat tersebut, kami harapkan kehadiran pimpinan perusahaan atau wakil yang diberi kuasa. Demikian kami sampaikan, atas perhatian dan kerja samanya kami ucapkan terima kasih.</p>${sigKetua()}${tembusan()}`);\n}\nfunction vendorNotes(v){return `<table class=\"g sm\"><tr><td style=\"width:30%\">Lokasi Plant</td><td>${esc(v?.plant||'')}</td></tr><tr><td>Pembayaran</td><td>${esc(P().bayarSingkat)}</td></tr><tr><td>Spesifikasi Material</td><td>${esc(P().material)}</td></tr><tr><td>Schedul Produksi</td><td>${esc(v?.schedul||'')}</td></tr><tr><td>Pengiriman</td><td>${esc(v?.kirim||'')}</td></tr><tr><td>Status WAVE</td><td>${esc(v?.wave||'')}</td></tr><tr><td>Approval Material</td><td>${esc(v?.approval||'')}</td></tr></table>`}\nfunction docBAA(v){\n  const p=P(),d=S.dok[2];let last='';\n  const rows=AAN_ROWS.map((r,i)=>{const sel=S.aan.sel[i]||[];let h='';if(r.sec!==last){last=r.sec;h=`<tr class=\"sec\"><td class=\"c\">${r.sec}</td><td colspan=\"3\">${r.grp}</td></tr>`}\n    return h+`<tr><td class=\"c\">${String.fromCharCode(97+i)}.</td><td>${esc(r.h)}</td><td>${r.o.map((o,j)=>`<span class=\"opt${sel.includes(j)?'':' no'}\"><span class=\"box\">${sel.includes(j)?'✓':''}</span>${esc(o)}</span>`).join(' ')}</td><td class=\"xs\">${esc(r.ket)}</td></tr>`}).join('');\n  return paper(`${formHead('BERITA ACARA PENJELASAN PENGADAAN BARANG, ALAT/JASA','BA AANWIJZING<br>PB-01B')}\n  <table class=\"meta\" style=\"margin-bottom:6pt\"><tr><td class=\"k\">Jenis Pekerjaan &amp; Lokasi</td><td class=\"c\">:</td><td>${esc(p.nama)} / ${esc(p.kota)}</td></tr><tr><td class=\"k\">Calon Penyedia Barang/Pemasok</td><td class=\"c\">:</td><td class=\"b\">${esc(v?v.nama:'Seluruh calon penyedia yang diundang')}</td></tr><tr><td class=\"k\">Jenis Material/Alat</td><td class=\"c\">:</td><td>${esc(p.material)}</td></tr><tr><td class=\"k\">Hari/Tanggal Rapat</td><td class=\"c\">:</td><td>${hariTgl(S.dok[1].acara||d.tgl)}, ${esc(S.dok[1].tempat||'')}</td></tr></table>\n  <table class=\"g sm\"><tr><th style=\"width:20pt\">No</th><th style=\"width:26%\">Uraian</th><th>Penjelasan (✓ = disepakati)</th><th style=\"width:24%\">Keterangan</th></tr><tr class=\"sec\"><td class=\"c\">A</td><td colspan=\"3\">UMUM — Nilai kinerja rekanan di WAVE; persyaratan mengacu pada Dokumen Tender/Kontrak</td></tr>${rows}</table>\n  <p class=\"b sm\" style=\"margin-bottom:2pt\">I. Catatan</p>${vendorNotes(v)}${S.aan.catatan?`<p class=\"sm\">${esc(S.aan.catatan)}</p>`:''}\n  <p class=\"sm i\">Berita Acara Penjelasan/Klarifikasi ini merupakan dokumen yang tidak terpisahkan dari Kontrak (SPK, SPP, SPPM).</p>\n  <p class=\"rt\">${esc(p.kotaTtd)}, ${tglID(d.tgl)}</p>\n  <div class=\"sig\" style=\"grid-template-columns:1fr 1fr\"><div class=\"s\">Calon Penyedia Barang/Jasa<br>${esc(v?v.nama:'')}<div class=\"sp\"></div><span class=\"nm\">( ${esc(v?v.pimpinan:'……………………')} )</span><br>${esc(v?v.jabatan:'')}</div><div class=\"s\">Ketua Tim Pengadaan<div class=\"sp\"></div><span class=\"nm\">( ${esc(T().ketua)} )</span><br>${esc(T().jabKetua)}</div></div>`);\n}\nfunction rfqNo(v){const base=S.dok[3].no||'';const idx=S.vendors.findIndex(x=>x.id===v?.id)+1;return idx>0?base.replace(/^(\\d+)/,`$1.${idx}`):base}\nfunction docRFQ(v){\n  const p=P(),d=S.dok[3];\n  return paper(`${kop()}${letterMeta(rfqNo(v),d.tgl)}${kepada(vendorTo(v))}${perihal(`Permintaan Penawaran Harga ${esc(p.nama)}`)}\n  <p>Dengan hormat,</p><p>Terkait akan dilaksanakannya ${esc(p.nama)} di ${esc(p.proyek)}, kami mengundang ${esc(v?v.nama:'Bapak/Ibu')} untuk ikut serta dalam proses pengadaan tersebut. Bersama ini kami sampaikan lampiran sebagai berikut:</p>\n  <p class=\"b\" style=\"margin-bottom:2pt\">A. Rincian kebutuhan</p>${itemTable(null,'rfq')}\n  <p class=\"b\" style=\"margin-bottom:2pt\">B. Spesifikasi teknis</p><ul>${S.items.map(it=>`<li>${esc(it.uraian)}: ${esc(it.spek)}</li>`).join('')}</ul>\n  <p class=\"b\" style=\"margin-bottom:2pt\">C. Tata cara pembayaran</p><ul><li>Jenis kontrak: ${esc(p.jenisKontrak)}; pengakuan progress: ${esc(p.progress)}</li><li>${esc(p.um)}; ${esc(p.bayar)}</li><li>Penyerahan: ${esc(p.serah)}, ${esc(p.lokasi)}</li></ul>\n  <p class=\"b\" style=\"margin-bottom:2pt\">D. Syarat-syarat penawaran</p><p>${esc(S.syaratRFQ)}</p>\n  <p>Untuk itu kami meminta agar diberikan penawaran terbaik untuk pekerjaan tersebut selambat-lambatnya tanggal <b>${tglID(d.acara)}</b>.</p><p>Demikian disampaikan, atas perhatiannya diucapkan terima kasih.</p>\n  ${sigKetua(true)}${tembusan(false)}`);\n}\nfunction klarOf(v){\n  if(!v)return null;\n  if(!S.klar[v.id]){const it=S.items[0]||{};S.klar[v.id]={mat_t:it.uraian||'',mat_u:'Sesuai',spek_t:it.spek||'',spek_u:'Sesuai',sat_t:it.satuan||'',sat_u:'Sesuai',ahli_t:'Tidak dipersyaratkan (suplai material)',ahli_u:'-',metode_t:'Pengiriman dump truck sesuai jadwal kebutuhan proyek',metode_u:'Sesuai',alat_t:'Dump truck / armada pengiriman',alat_u:'Sesuai',catatan:''}}\n  return S.klar[v.id];\n}\nfunction docUndNego(v){\n  const p=P(),d=S.dok[4];\n  return paper(`${kop()}${letterMeta(d.no,d.tgl)}${kepada(vendorTo(v))}${perihal(`Undangan Klarifikasi Teknis dan Negosiasi Harga<br>${esc(p.metode)} ${esc(p.nama)} ${esc(p.proyek)}`)}\n  <p>Dengan hormat,</p><p>Sehubungan dengan telah dikirimnya dokumen penawaran teknis dan biaya oleh calon penyedia barang/jasa untuk ${esc(p.metode)} ${esc(p.nama)}, bersama ini kami mengundang Bapak/Ibu dalam kegiatan klarifikasi teknis dan negosiasi harga yang akan dilaksanakan pada:</p>\n  <table class=\"meta\" style=\"margin:0 0 9pt 18pt;width:auto\"><tr><td class=\"k\">Hari/Tanggal</td><td class=\"c\">:</td><td>${hariTgl(d.acara)}</td></tr><tr><td class=\"k\">Waktu</td><td class=\"c\">:</td><td>${esc(d.jam||'……')}</td></tr><tr><td class=\"k\">Tempat</td><td class=\"c\">:</td><td>${esc(d.tempat||'……')}</td></tr><tr><td class=\"k\">Agenda</td><td class=\"c\">:</td><td>Rapat Klarifikasi &amp; Negosiasi Harga Final</td></tr><tr><td class=\"k\">Dokumen disiapkan</td><td class=\"c\">:</td><td>1. Berita Acara Klarifikasi &amp; Negosiasi sebelumnya<br>2. Penawaran harga terakhir</td></tr></table>\n  <p>Apabila klarifikasi teknis dan negosiasi harga tersebut di atas tidak dapat dihadiri oleh direktur yang berwenang, maka yang mewakilinya harus menyertakan surat kuasa bermeterai cukup dan dokumen aslinya dikirim kepada Tim Pengadaan ${esc(p.material)}.</p><p>Demikian kami sampaikan, atas perhatiannya diucapkan terima kasih.</p>${sigKetua()}${tembusan()}`);\n}\nfunction docBAN(v){\n  const p=P(),d=S.dok[5],k=klarOf(v)||{};\n  const tr=(no,l,t,u)=>`<tr><td class=\"c\">${no}</td><td>${l}</td><td>${esc(t)}</td><td>${esc(u)}</td></tr>`;\n  const harga=S.items.map((it,i)=>{const a=N(it.awal?.[v?.id]),f=N(it.final?.[v?.id]);return `<tr><td>${esc(it.uraian)}</td><td class=\"r\">${fmt(it.vol)}</td><td class=\"r\">${fmt(a)}</td><td class=\"r\">${fmt(a*N(it.vol))}</td><td class=\"r\">${fmt(it.vol)}</td><td class=\"r\">${fmt(f)}</td><td class=\"r\">${fmt(f*N(it.vol))}</td></tr>`}).join('');\n  const t=v?C.tot[v.id]:{awal:0,final:0};\n  return paper(`${formHead('BERITA ACARA PENJELASAN/KLARIFIKASI PENYEDIA BARANG, ALAT/JASA','BA KLAR &amp; NEGO<br>PB-01B-2')}\n  <table class=\"meta\" style=\"margin-bottom:6pt\"><tr><td class=\"k\">Jenis Pekerjaan &amp; Lokasi</td><td class=\"c\">:</td><td>${esc(p.nama)} / ${esc(p.kota)}</td></tr><tr><td class=\"k\">Calon Penyedia Barang/Pemasok</td><td class=\"c\">:</td><td class=\"b\">${esc(v?.nama||'-')}</td></tr><tr><td class=\"k\">Jenis Material/Alat</td><td class=\"c\">:</td><td>${esc(p.material)}</td></tr></table>\n  <table class=\"g sm\"><tr><th style=\"width:20pt\">No</th><th style=\"width:30%\">Uraian</th><th>Persyaratan Tender</th><th>Usulan Rekanan / Penawaran</th></tr>\n  <tr class=\"sec\"><td class=\"c\">A</td><td colspan=\"3\">PERSYARATAN UMUM</td></tr>\n  <tr><td></td><td colspan=\"3\">1. Apabila ditunjuk sebagai pemenang, Mitra Kerja menyatakan sanggup dan bersedia melaksanakan pekerjaan/pengadaan sesuai draf kontrak yang diterima dari ${esc(p.perusahaan)} pada saat proses klarifikasi dan negosiasi.<br>2. Hal-hal yang belum tercantum dalam Berita Acara ini mengikuti Berita Acara Klarifikasi sebelumnya / ketentuan di Proyek / Business Unit.</td></tr>\n  <tr class=\"sec\"><td class=\"c\">B</td><td colspan=\"3\">LINGKUP PEKERJAAN</td></tr>\n  <tr><td></td><td colspan=\"3\">1. ${esc(p.nama)}<br>2. Pengiriman material sampai ke ${esc(p.lokasi)}<br>3. Pengamanan mutu selama proses pengiriman</td></tr>\n  <tr class=\"sec\"><td class=\"c\">C</td><td colspan=\"3\">TEKNIS</td></tr>\n  ${tr('1a','Material',k.mat_t,k.mat_u)}${tr('1b','Spesifikasi',k.spek_t,k.spek_u)}${tr('1c','Satuan',k.sat_t,k.sat_u)}${tr('2','Tenaga Ahli/IPTB/SKA/SKT',k.ahli_t,k.ahli_u)}${tr('3','Metode Kerja',k.metode_t,k.metode_u)}${tr('4','Alat/Peralatan Utama',k.alat_t,k.alat_u)}\n  </table>\n  <p class=\"b sm\" style=\"margin:2pt 0\">D. Harga Penawaran (Rp, belum PPN)</p>\n  <table class=\"g sm\"><tr><th rowspan=\"2\">Item</th><th colspan=\"3\">Penawaran Awal</th><th colspan=\"3\">Penawaran Akhir</th></tr><tr><th>Volume</th><th>Harsat</th><th>Jumlah</th><th>Volume</th><th>Harsat</th><th>Jumlah</th></tr>${harga}<tr class=\"tot\"><td>JUMLAH</td><td colspan=\"3\" class=\"r\">${fmt(t.awal)}</td><td colspan=\"3\" class=\"r\">${fmt(t.final)}</td></tr><tr><td colspan=\"7\" class=\"sm\">Terbilang (akhir): <i>${terbilang(t.final)}</i>; turun ${t.awal?pct((t.awal-t.final)/t.awal):'-'} dari penawaran awal.</td></tr></table>\n  <p class=\"b sm\" style=\"margin:2pt 0\">E. Catatan / Lain-lain</p>${vendorNotes(v)}${k.catatan?`<p class=\"sm\"><b>Catatan khusus:</b> ${esc(k.catatan)}</p>`:''}\n  <p class=\"sm i\">Berita Acara Penjelasan/Klarifikasi ini merupakan dokumen yang tidak terpisahkan dari Kontrak (SPK, SPP, SPPM).</p>\n  <p class=\"rt\">${esc(p.kotaTtd)}, ${tglID(d.tgl)}</p>\n  <div class=\"sig\" style=\"grid-template-columns:1fr 1fr\"><div class=\"s\">Calon Penyedia Barang/Jasa<br>${esc(v?.nama||'')}<div class=\"sp\"></div><span class=\"nm\">( ${esc(v?.pimpinan||'……………')} )</span><br>${esc(v?.jabatan||'')}</div><div class=\"s\">Ketua Tim Pengadaan<div class=\"sp\"></div><span class=\"nm\">( ${esc(T().ketua)} )</span><br>${esc(T().jabKetua)}</div></div>`);\n}\nfunction docEVH(){\n  const p=P(),d=S.dok[6],pb=C.pemb;\n  const ppn=N(p.ppn);\n  const head=pb.map(x=>`<th colspan=\"3\">${esc(x.name||'—')}</th>`).join('');\n  const sub=pb.map(()=>'<th>Vol</th><th>Harsat</th><th>Jumlah</th>').join('');\n  const rows=S.items.map((it,i)=>`<tr><td class=\"c\">${i+1}</td><td>${esc(it.uraian)}<br><span class=\"xs\">${esc(it.spek)}</span></td><td class=\"c\">${esc(it.satuan)}</td><td class=\"r\">${fmt(it.vol)}</td><td class=\"r\">${fmt(it.hps)}</td><td class=\"r\">${fmt(N(it.vol)*N(it.hps))}</td>${pb.map(x=>{const h=x.v?N(it.final?.[x.v.id]):0;return `<td class=\"r\">${fmt(it.vol)}</td><td class=\"r\">${fmt(h)}</td><td class=\"r\">${fmt(h*N(it.vol))}</td>`}).join('')}</tr>`).join('');\n  const line=(lbl,f)=>`<tr class=\"tot\"><td colspan=\"5\" class=\"r\">${lbl}</td><td class=\"r\">${fmt(f(C.hps))}</td>${pb.map(x=>`<td colspan=\"3\" class=\"r\">${fmt(f(x.final))}</td>`).join('')}</tr>`;\n  return paper(`${formHead('EVALUASI HARGA FINAL CALON PENYEDIA BARANG/JASA','PB-01A')}\n  <table class=\"meta\" style=\"margin-bottom:4pt\"><tr><td class=\"k\">Pekerjaan / Lokasi</td><td class=\"c\">:</td><td>${esc(p.nama)} / ${esc(p.kota)}</td></tr></table>\n  <table class=\"g sm\"><tr><th rowspan=\"2\">No</th><th rowspan=\"2\">Uraian Bahan</th><th rowspan=\"2\">Sat</th><th colspan=\"3\">Sesuai dengan APP/HPS</th>${head}</tr><tr><th>Vol</th><th>Harsat</th><th>Jumlah</th>${sub}</tr>${rows}\n  ${line('JUMLAH',x=>x)}${line('PPN '+pct(ppn,0),x=>Math.round(x*ppn))}${line('TOTAL',x=>x+Math.round(x*ppn))}\n  <tr><td colspan=\"5\" class=\"r\">Nilai Penawaran (∑PA / ∑APP × 100)</td><td class=\"r\">100,00</td>${pb.map(x=>`<td colspan=\"3\" class=\"r\">${C.hps?fmtD(x.final/C.hps*100):'-'}</td>`).join('')}</tr>\n  <tr><td colspan=\"5\" class=\"r\">Peringkat (harga final terendah)</td><td></td>${pb.map(x=>`<td colspan=\"3\" class=\"c b\">${x.rank??'-'}</td>`).join('')}</tr></table>\n  <div style=\"display:grid;grid-template-columns:1.3fr 1fr;gap:14pt\"><div><p class=\"b sm\" style=\"margin-bottom:2pt\">Syarat-syarat</p><table class=\"meta sm\"><tr><td>1.</td><td>Pembayaran</td><td>: ${esc(p.um)}, ${esc(p.bayarSingkat)}</td></tr><tr><td>2.</td><td>Waktu Penyerahan</td><td>: ${esc(p.serah)}</td></tr><tr><td>3.</td><td>Tempat Penyerahan</td><td>: ${esc(p.lokasi)}</td></tr><tr><td>4.</td><td>Asuransi</td><td>: ${esc(p.asuransi)}</td></tr></table></div>\n  <div><p class=\"rt\">${esc(p.kotaTtd)}, ${tglID(d.tgl)}</p></div></div>${teamSig()}`,true);\n}\nfunction docEVP(){\n  const p=P(),d=S.dok[7],pb=C.pemb;let last='';\n  const rows=KRIT.map((k,i)=>{let h='';if(k.g!==last){last=k.g;h=`<tr class=\"sec\"><td class=\"c\">${k.g}</td><td colspan=\"${3+pb.length*2}\">${k.grp}</td></tr>`}\n    return h+`<tr><td class=\"c\">${String.fromCharCode(97+KRIT.filter((x,j)=>x.g===k.g&&j<i).length)}.</td><td>${esc(k.label)}</td><td class=\"c\">${fmtD(S.bobot[i],0)}</td>${pb.map(x=>{const n=x.v?C.nilaiOf(x.v.id,i):0;return `<td class=\"r\">${fmtD(n,2)}</td><td class=\"r\">${fmtD(N(S.bobot[i])*n,2)}</td>`}).join('')}<td class=\"xs\">${esc(k.ket)}</td></tr>`}).join('');\n  return paper(`${formHead('EVALUASI PENAWARAN PENYEDIA BARANG/JASA (SUPLIER)','PB-01.2')}\n  <table class=\"meta\" style=\"margin-bottom:4pt\"><tr><td class=\"k\">Jenis Pekerjaan</td><td class=\"c\">:</td><td>${esc(p.nama)}</td><td class=\"k\" style=\"padding-left:20pt\">Lokasi</td><td class=\"c\">:</td><td>${esc(p.lokasi)}</td></tr></table>\n  <table class=\"g xs\"><tr><th rowspan=\"2\">No</th><th rowspan=\"2\">Uraian Penilaian</th><th rowspan=\"2\">Bobot</th>${pb.map(x=>`<th colspan=\"2\">${esc(x.name||'—')}</th>`).join('')}<th rowspan=\"2\" style=\"width:28%\">Keterangan</th></tr><tr>${pb.map(()=>'<th>Nilai</th><th>Skor</th>').join('')}</tr>${rows}\n  <tr class=\"tot\"><td colspan=\"2\" class=\"r\">JUMLAH</td><td class=\"c\">${fmtD(C.bobotTot,0)}</td>${pb.map(x=>`<td></td><td class=\"r\">${fmtD(x.skor)}</td>`).join('')}<td rowspan=\"2\">Rekomendasi: <b>${esc(C.rek?C.rek.name:'-')}</b> (harga final terendah)</td></tr>\n  <tr class=\"tot\"><td colspan=\"3\" class=\"r\">PERINGKAT</td>${pb.map(x=>`<td colspan=\"2\" class=\"c\">${x.rankSkor??'-'}</td>`).join('')}</tr></table>\n  <p class=\"rt\" style=\"margin:0\">${esc(p.kotaTtd)}, ${tglID(d.tgl)}</p>${teamSig()}`,true);\n}\nfunction docBAP(){\n  const p=P(),d=S.dok[8],w=C.win.v,t=T();\n  const team=[[t.ketua,'Ketua'],[t.sekretaris,'Sekretaris'],...t.anggota.filter(Boolean).map(a=>[a,'Anggota'])];\n  const lamp=['Penawaran Penyedia Barang/Jasa Pemenang','Form PB-01 Evaluasi Penawaran Penyedia Barang/Jasa','Form PB-01A Penawaran Harga Penyedia Barang/Jasa Terseleksi','Form PB-01B Berita Acara Penjelasan Penyedia Barang/Jasa','Form PB-01B-2 Berita Acara Klarifikasi/Negosiasi Penyedia Barang/Jasa','Form PB-02 Surat Pernyataan Kesanggupan','Form PB-03 Pra-Kualifikasi K3LMP Penyedia Barang/Jasa (WAVE)','Form PB-04 Pra-Kualifikasi Penyedia Barang/Jasa (WAVE)','Form PB-05 Penilaian Mandor Borong (WAVE)','Form PB-06 Evaluasi Kinerja Penyedia Barang/Jasa (WAVE)'];\n  const e=C.hpsPpn-C.finalPpn;\n  return paper(`${kop()}<table class=\"meta sm\"><tr><td class=\"k\">Business Unit/Unit Kerja</td><td class=\"c\">:</td><td>${esc(p.unit)}</td></tr><tr><td class=\"k\">Proyek dan ID Proyek</td><td class=\"c\">:</td><td>${esc(p.proyek)} / ${esc(p.idProyek)}</td></tr></table>\n  <h1>BERITA ACARA PENENTUAN PEMENANG PENYEDIA BARANG/JASA</h1><p class=\"ctr\">No.: ${esc(d.no)}, Tanggal: ${tglID(d.tgl)}</p>\n  <p class=\"ctr sm\" style=\"margin-bottom:8pt\">Jenis Pekerjaan &amp; Lokasi: ${esc(p.nama)} / ${esc(p.kota)} <span class=\"tag\">PB-10</span></p>\n  <p>Pada hari ini ${tglKalimat(d.tgl)} di ${esc(p.kotaTtd)} telah dilaksanakan Rapat Penentuan Pemenang Penyedia Barang/Jasa untuk pekerjaan di atas, sebagai berikut:</p>\n  <table class=\"meta\" style=\"margin:0 0 8pt 10pt;width:auto\"><tr><td class=\"k\">1. Nama Pemenang</td><td class=\"c\">:</td><td class=\"b\">${esc(w?.nama||'-')}</td></tr><tr><td class=\"k\">&nbsp;&nbsp;&nbsp;&nbsp;Alamat</td><td class=\"c\">:</td><td>${esc(w?.alamat||'-')}</td></tr><tr><td class=\"k\">&nbsp;&nbsp;&nbsp;&nbsp;Kontak</td><td class=\"c\">:</td><td>${esc(w?.telp||'')} / ${esc(w?.email||'')}</td></tr>\n  <tr><td class=\"k\">2. Harga APP/HPS (termasuk PPN)</td><td class=\"c\">:</td><td>Rp ${fmt(C.hpsPpn)}</td></tr><tr><td class=\"k\">3. Harga Pemenang (termasuk PPN)</td><td class=\"c\">:</td><td>Rp ${fmt(C.finalPpn)}</td></tr><tr><td class=\"k\">4. Efisiensi (2 − 3)</td><td class=\"c\">:</td><td>Rp ${fmt(e)}</td></tr><tr><td class=\"k\">5. Efisiensi (4 / 2) × 100%</td><td class=\"c\">:</td><td>${C.hpsPpn?fmtD(e/C.hpsPpn*100):'0,00'} %</td></tr></table>\n  <p style=\"margin-bottom:2pt\">Lampiran:</p><ul class=\"sm\" style=\"list-style:none;padding-left:8pt\">${lamp.map(l=>`<li><span class=\"box\">✓</span>${esc(l)}</li>`).join('')}${S.catatanPB10?`<li><span class=\"box\">✓</span>Lain-lain: ${esc(S.catatanPB10)}</li>`:''}</ul>\n  <p>Demikian Berita Acara ini dibuat untuk dapat dilaksanakan dan diproses lebih lanjut.</p>\n  <p class=\"sm\" style=\"margin-bottom:2pt\">Pelaksana Pengadaan (seluruh Tim Pengadaan):</p>\n  <table class=\"g sm\"><tr><th style=\"width:24pt\">No</th><th>Nama</th><th>Jabatan</th><th style=\"width:34%\">Tanda Tangan</th></tr>${team.map((r,i)=>`<tr style=\"height:24pt\"><td class=\"c\">${i+1}</td><td>${esc(r[0])}</td><td>${r[1]}</td><td style=\"${i%2?'padding-left:50%':''}\">${i+1}.</td></tr>`).join('')}</table>`);\n}\nfunction docPENG(){\n  const p=P(),d=S.dok[9],pb=C.pemb;\n  const batas=addDays(d.tgl,2);\n  const nego=S.dok[4].acara||S.dok[5].tgl;\n  return paper(`${kop()}<table class=\"meta\" style=\"width:auto;margin-bottom:8pt\"><tr><td class=\"k\">Nomor</td><td class=\"c\">:</td><td>${esc(d.no)}</td></tr><tr><td class=\"k\">Tanggal</td><td class=\"c\">:</td><td>${tglID(d.tgl)}</td></tr></table>\n  <p style=\"text-align:left\">Kepada Yth.<br>${pb.filter(x=>x.v).map((x,i)=>`${i+1}. ${esc(x.v.jabatan)} ${esc(x.name)}`).join('<br>')}<br>di –<br><span style=\"padding-left:14pt\">Tempat</span></p>\n  ${perihal(`Pengumuman Pemenang ${esc(p.nama)}`)}\n  <p>Dengan hormat,</p><p>Berdasarkan hasil evaluasi klarifikasi teknis dan negosiasi harga penawaran penyedia barang/jasa oleh Tim Pengadaan pada ${hariTgl(nego)}, bersama ini kami mengumumkan pemenang pengadaan dengan uraian sebagai berikut:</p>\n  <p class=\"b\" style=\"margin-bottom:2pt\">1. Paket Pekerjaan</p><table class=\"meta\" style=\"margin:0 0 6pt 12pt\"><tr><td class=\"k\">Nama Paket</td><td class=\"c\">:</td><td>${esc(p.nama)}</td></tr><tr><td class=\"k\">Deskripsi Pengadaan</td><td class=\"c\">:</td><td>${esc(p.deskripsi)}</td></tr><tr><td class=\"k\">Sumber Pendanaan</td><td class=\"c\">:</td><td>${esc(p.dana)}</td></tr><tr><td class=\"k\">HPS (belum PPN)</td><td class=\"c\">:</td><td>Rp ${fmt(C.hps)}</td></tr></table>\n  <p class=\"b\" style=\"margin-bottom:2pt\">2. Hasil Evaluasi</p>\n  <table class=\"g sm\"><tr><th style=\"width:20pt\">No</th><th style=\"width:22%\">Kriteria Evaluasi</th>${pb.map(x=>`<th>${esc(x.name||'—')}</th>`).join('')}</tr>\n  <tr><td class=\"c\">1</td><td>NPWP</td>${pb.map(x=>`<td>${esc(x.v?.npwp||'')}</td>`).join('')}</tr><tr><td class=\"c\">2</td><td>Alamat</td>${pb.map(x=>`<td>${esc(x.v?.alamat||'')}</td>`).join('')}</tr><tr><td class=\"c\">3</td><td>Harga Final (belum PPN)</td>${pb.map(x=>`<td class=\"r\">${fmt(x.final)}</td>`).join('')}</tr><tr><td class=\"c\">4</td><td>Hasil Pemilihan</td>${pb.map(x=>`<td class=\"c b\">${C.win.ok&&x.v&&x.v.id===C.win.v.id?'PEMENANG':'Pembanding '+(x.rank?'(peringkat '+x.rank+')':'')}</td>`).join('')}</tr></table>\n  <p>Bagi penyedia lain yang ingin mengajukan sanggahan, paling lambat diajukan <b>2 (dua) hari kalender</b> setelah surat ini dikeluarkan (sampai dengan ${hariTgl(batas)}) disertai Surat Pernyataan Pengajuan Sanggahan dan bukti pendukung yang sah.</p>\n  <p>Apabila terbukti bahwa sanggahan diajukan tanpa didasari bukti yang sah dan benar, maka akan diberikan sanksi untuk tidak mengikuti pengadaan di lingkungan ${esc(p.perusahaan)} selama 6 (enam) bulan sejak tanggal pengajuan.</p>\n  <p>Demikian pengumuman pemenang ini kami sampaikan, atas perhatian dan kerja samanya diucapkan terima kasih.</p>${sigKetua()}<div class=\"foot\">Tembusan:<ol style=\"margin:0\"><li>${esc(p.tembusan)}</li><li>Arsip</li></ol></div>`);\n}\nfunction docUSUL(){\n  const p=P(),d=S.dok[10],w=C.win.v;\n  return paper(`${kop()}${letterMeta(d.no,d.tgl)}<p style=\"text-align:left\">Kepada Yth.<br>${esc(p.tujuanUsulan)}<br>${esc(p.perusahaan)}<br>di –<br><span style=\"padding-left:14pt\">${esc(p.kotaTtd)}</span></p>\n  ${perihal(`Laporan dan Usulan Pemenang Pekerjaan<br>${esc(p.nama)}`)}\n  <p>Dengan hormat,</p><p>Sehubungan dengan telah diumumkannya pemenang ${esc(p.nama)} ${esc(p.proyek)} melalui surat Nomor ${esc(S.dok[9].no)} tanggal ${tglID(S.dok[9].tgl)}, dan tidak adanya sanggahan dari peserta pengadaan sampai dengan batas waktu ${tglID(addDays(S.dok[9].tgl,2))}, bersama ini kami selaku Tim Pengadaan menyampaikan usulan dengan rincian sebagai berikut:</p>\n  <table class=\"g\"><tr><td style=\"width:36%\">Nama Paket</td><td>${esc(p.nama)}</td></tr><tr><td>Metode Pengadaan</td><td>${esc(p.metode)}</td></tr><tr><td>Usulan Pemenang</td><td class=\"b\">${esc(w?.nama||'-')}</td></tr><tr><td>NPWP / Alamat</td><td>${esc(w?.npwp||'')} / ${esc(w?.alamat||'')}</td></tr><tr><td>HPS (belum PPN)</td><td class=\"r\">${fmt(C.hps)}</td></tr><tr><td>Harga Final (belum PPN)</td><td class=\"r\">${fmt(C.final)}</td></tr><tr><td>PPN ${pct(N(p.ppn),0)}</td><td class=\"r\">${fmt(C.ppn)}</td></tr><tr class=\"tot\"><td>Harga Final (termasuk PPN)</td><td class=\"r\">${fmt(C.finalPpn)}</td></tr><tr><td>Terbilang</td><td class=\"i\">${terbilang(C.finalPpn)}</td></tr><tr><td>Efisiensi terhadap HPS</td><td class=\"r\">Rp ${fmt(C.efis)} (${pct(C.efisPct)})</td></tr><tr><td>Skor PB-01.2</td><td class=\"r\">${fmtD(C.pemb.find(x=>x.v&&w&&x.v.id===w.id)?.skor||0)}</td></tr></table>\n  <p style=\"margin-bottom:2pt\">Sebagai bahan pertimbangan, terlampir:</p><ol><li>Surat Pengumuman Pemenang</li><li>Form PB-01, PB-01A, PB-01B, PB-01B-2, PB-01.2 dan PB-10</li><li>Dokumen pendukung lainnya</li></ol>\n  <p>Demikian kami sampaikan, mohon untuk diberikan arahan lebih lanjut. Atas perhatian yang diberikan kami ucapkan terima kasih.</p>\n  <div class=\"letter-sig\">Hormat kami,<br>Ketua Tim Pengadaan ${esc(p.material)}<div class=\"sp\"></div><div class=\"nm\">${esc(T().ketua)}</div>${esc(T().jabKetua)}</div><div class=\"foot\">Lampiran : 1 (satu) berkas<br>Tembusan : Arsip</div>`);\n}\nfunction docTETAP(){\n  const p=P(),d=S.dok[11],w=C.win.v,pg=S.dok[9];\n  return paper(`${kop()}${letterMeta(d.no,d.tgl)}<p style=\"text-align:left\">Kepada Yth.<br>${esc(w?.jabatan||'Direktur')}<br><b>${esc(w?.nama||'-')}</b><br>${esc(w?.alamat||'')}<br>E-mail: ${esc(w?.email||'')}</p>\n  ${perihal(`Penetapan Pemenang ${esc(p.metode)} ${esc(p.nama)}`)}\n  <p>Dengan hormat,</p><p>Sehubungan dengan telah disampaikannya Pengumuman Pemenang ${esc(p.metode)} ${esc(p.nama)} ${esc(p.proyek)} Nomor ${esc(pg.no)} pada ${tglKalimat(pg.tgl).replace(/^\\S+ /,'')}, bersama ini kami melakukan penunjukan pemenang pengadaan dengan uraian sebagai berikut:</p>\n  <p class=\"b\" style=\"margin-bottom:2pt\">1. Paket Pekerjaan</p><p style=\"margin-left:14pt\">Nama paket pekerjaan: ${esc(p.nama)}</p>\n  <p class=\"b\" style=\"margin-bottom:2pt\">2. Pemenang</p><table class=\"meta\" style=\"margin:0 0 6pt 14pt\"><tr><td class=\"k\">Nama</td><td class=\"c\">:</td><td class=\"b\">${esc(w?.nama||'-')}</td></tr><tr><td class=\"k\">NPWP</td><td class=\"c\">:</td><td>${esc(w?.npwp||'')}</td></tr><tr><td class=\"k\">Alamat</td><td class=\"c\">:</td><td>${esc(w?.alamat||'')}</td></tr></table>\n  <p class=\"b\" style=\"margin-bottom:2pt\">3. Harga Final</p><table class=\"meta\" style=\"margin:0 0 6pt 14pt\"><tr><td class=\"k\">Nilai Paket Pekerjaan</td><td class=\"c\">:</td><td class=\"b\">Rp ${fmt(C.finalPpn)},- (termasuk PPN ${pct(N(p.ppn),0)})</td></tr><tr><td class=\"k\">Terbilang</td><td class=\"c\">:</td><td class=\"i\">${terbilang(C.finalPpn)}</td></tr><tr><td class=\"k\">Rincian</td><td class=\"c\">:</td><td>Harga Rp ${fmt(C.final)} + PPN Rp ${fmt(C.ppn)}</td></tr></table>\n  <p class=\"b\" style=\"margin-bottom:2pt\">4. Syarat-syarat yang berlaku, antara lain:</p><ol type=\"a\" style=\"margin-left:14pt\"><li>${esc(p.um)}</li><li>${esc(p.bayar)}</li><li>Tempat penyerahan: ${esc(p.lokasi)}</li><li>Jangka waktu: ${esc(p.waktu)}; jenis kontrak ${esc(p.jenisKontrak)}</li></ol>\n  <p>Demikian penetapan pemenang ini kami sampaikan. Kami ucapkan terima kasih kepada seluruh peserta yang telah berpartisipasi dalam pengadaan ini.</p>\n  <div class=\"letter-sig\" style=\"width:75mm\">Hormat kami,<br>${esc(P().perusahaan)}<br>${esc(T().jabPenetap1)}<br>${esc(T().jabPenetap2)}<div class=\"sp\"></div><div class=\"nm\">${esc(T().penetap)}</div></div>\n  <div class=\"foot\">Lampiran : -<br>Tembusan :<ol style=\"margin:0\"><li>${esc(p.tembusan)}</li><li>Arsip</li></ol></div>`);\n}\nfunction docsForStage(n,all){\n  const pv=pembVendors();\n  switch(n){\n    case 1:return docParam();\n    case 2:return docVendor();\n    case 3:return docHPS();\n    case 4:return all&&S.sel.und!=='all'?S.vendors.map(docUndangan).join(''):vendorsFor(S.sel.und).map(docUndangan).join('');\n    case 5:return all&&S.sel.unda!=='all'?S.vendors.map(docUndAan).join(''):vendorsFor(S.sel.unda).map(docUndAan).join('');\n    case 6:return all?(pv.length?pv:[null]).map(docBAA).join(''):docBAA(S.aan.untuk==='all'?null:C.vById(S.aan.untuk));\n    case 7:return all?S.vendors.map(docRFQ).join(''):docRFQ(C.vById(S.sel.rfq)||S.vendors[0]);\n    case 8:{const list=all?pv:[C.pemb[S.sel.klar]?.v].filter(Boolean);return list.map(v=>docUndNego(v)+docBAN(v)).join('')||'<p style=\"color:#fff\">Pilih pembanding yang valid.</p>'}\n    case 9:return docEVH();\n    case 10:return docEVP();\n    case 11:return docBAP()+docPENG();\n    case 12:return docUSUL()+docTETAP();\n  }\n  return '';\n}\n\n/* =========================================================\n   GRAFIK (SVG)\n   ========================================================= */\nfunction niceTicks(min,max,n){const span=max-min;const step0=span/n;const mag=Math.pow(10,Math.floor(Math.log10(step0)));const st=[1,2,2.5,5,10].map(x=>x*mag).find(x=>x>=step0);const out=[];for(let v=Math.ceil(min/st)*st;v<=max+1e-6;v+=st)out.push(v);return out}\nfunction chartDumbbell(){\n  const vs=S.vendors.filter(v=>C.tot[v.id].awal>0||C.tot[v.id].final>0);\n  if(!vs.length)return '<p class=\"note\">Belum ada penawaran.</p>';\n  const W=720,L=210,R=24,T=26,rh=30,H=T+vs.length*rh+30;\n  const vals=vs.flatMap(v=>[C.tot[v.id].awal,C.tot[v.id].final]).concat([C.hps]).filter(x=>x>0);\n  let mn=Math.min(...vals),mx=Math.max(...vals);const pad=(mx-mn)*.08||mx*.02;mn-=pad;mx+=pad;\n  const x=v=>L+(v-mn)/(mx-mn)*(W-L-R);\n  const ticks=niceTicks(mn,mx,5);\n  const pembIds=C.pemb.filter(p=>p.ok).map(p=>p.v.id);\n  let g=ticks.map(t=>`<line x1=\"${x(t)}\" x2=\"${x(t)}\" y1=\"${T-6}\" y2=\"${H-26}\" stroke=\"var(--line)\" stroke-width=\"1\"/><text x=\"${x(t)}\" y=\"${H-10}\" text-anchor=\"middle\">${fmtD(t/1e9,2)} M</text>`).join('');\n  g+=`<line x1=\"${x(C.hps)}\" x2=\"${x(C.hps)}\" y1=\"${T-14}\" y2=\"${H-26}\" stroke=\"var(--accent)\" stroke-width=\"2\" stroke-dasharray=\"5 3\"/><text x=\"${x(C.hps)}\" y=\"${T-16}\" text-anchor=\"middle\" style=\"fill:var(--accent)\">HPS ${fmtD(C.hps/1e9,3)} M</text>`;\n  vs.forEach((v,i)=>{const y=T+i*rh+rh/2,a=C.tot[v.id].awal,f=C.tot[v.id].final,isP=pembIds.includes(v.id),isW=C.win.ok&&C.win.v.id===v.id;\n    const nm=v.nama.length>28?v.nama.slice(0,27)+'…':v.nama;\n    g+=`<text x=\"${L-10}\" y=\"${y+4}\" text-anchor=\"end\" style=\"fill:${isP?'var(--fg)':'var(--muted)'};font-family:var(--f-body);font-size:12px;font-weight:${isW?600:400}\">${isW?'★ ':''}${esc(nm)}</text>`;\n    g+=`<line x1=\"${x(a)}\" x2=\"${x(f)}\" y1=\"${y}\" y2=\"${y}\" stroke=\"${isP?'var(--muted)':'var(--line2)'}\" stroke-width=\"3\"/>`;\n    g+=`<circle cx=\"${x(a)}\" cy=\"${y}\" r=\"5\" fill=\"var(--panel)\" stroke=\"var(--muted)\" stroke-width=\"2\"/><circle cx=\"${x(f)}\" cy=\"${y}\" r=\"6\" fill=\"${f>C.hps?'var(--bad)':'var(--ok)'}\"/>`;\n  });\n  return `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Penawaran awal dan final per vendor\">${g}</svg><div class=\"legend\"><span><i style=\"background:var(--panel);border:2px solid var(--muted)\"></i>Penawaran awal</span><span><i style=\"background:var(--ok)\"></i>Final ≤ HPS</span><span><i style=\"background:var(--bad)\"></i>Final &gt; HPS</span><span><i style=\"background:var(--accent)\"></i>Garis HPS</span><span>★ Pemenang · nama terang = pembanding</span></div>`;\n}\nfunction chartTurun(){\n  const vs=S.vendors.map(v=>{const t=C.tot[v.id];return {v,d:t.awal?(t.awal-t.final)/t.awal:0}});\n  const W=420,L=150,R=56,rh=26,H=vs.length*rh+10;const mx=Math.max(.01,...vs.map(o=>o.d))*1.05;\n  const pembIds=C.pemb.filter(p=>p.ok).map(p=>p.v.id);\n  return `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Persentase turun hasil negosiasi\">${vs.map((o,i)=>{const y=5+i*rh,w=Math.max(0,o.d)/mx*(W-L-R);const nm=o.v.nama.length>20?o.v.nama.slice(0,19)+'…':o.v.nama;const isP=pembIds.includes(o.v.id);\n    return `<text x=\"${L-8}\" y=\"${y+15}\" text-anchor=\"end\" style=\"font-family:var(--f-body);font-size:11.5px;fill:${isP?'var(--fg)':'var(--muted)'}\">${esc(nm)}</text><rect x=\"${L}\" y=\"${y+4}\" width=\"${w}\" height=\"16\" rx=\"2\" fill=\"${isP?'var(--accent)':'var(--line2)'}\"/><text x=\"${L+w+6}\" y=\"${y+16}\">${fmtD(o.d*100)}%</text>`}).join('')}</svg>`;\n}\nfunction chartRadar(){\n  const pb=C.pemb.filter(p=>p.ok);const W=360,H=330,cx=180,cy=165,r=118;const n=GRUP.length;\n  const ang=i=>-Math.PI/2+i*2*Math.PI/n;const pt=(i,v)=>[cx+Math.cos(ang(i))*r*v,cy+Math.sin(ang(i))*r*v];\n  let g='';[.25,.5,.75,1].forEach(l=>{g+=`<polygon points=\"${GRUP.map((_,i)=>pt(i,l).join(',')).join(' ')}\" fill=\"none\" stroke=\"var(--line)\" stroke-width=\"1\"/>`});\n  GRUP.forEach((gr,i)=>{const [x2,y2]=pt(i,1);const [lx,ly]=pt(i,1.17);g+=`<line x1=\"${cx}\" y1=\"${cy}\" x2=\"${x2}\" y2=\"${y2}\" stroke=\"var(--line)\"/><text x=\"${lx}\" y=\"${ly+4}\" text-anchor=\"middle\" style=\"font-family:var(--f-body);font-size:11px\">${gr[1]}</text>`});\n  const cols=['var(--s1)','var(--s2)','var(--s3)'];\n  pb.forEach(p=>{const vals=GRUP.map(gr=>{let b=0,s=0;KRIT.forEach((k,i)=>{if(k.g===gr[0]){b+=N(S.bobot[i]);s+=N(S.bobot[i])*C.nilaiOf(p.v.id,i)}});return b?s/b:0});\n    g+=`<polygon points=\"${vals.map((v,i)=>pt(i,v).join(',')).join(' ')}\" fill=\"${cols[p.pos]}\" fill-opacity=\".14\" stroke=\"${cols[p.pos]}\" stroke-width=\"2\"/>`;\n    vals.forEach((v,i)=>{const [a,b]=pt(i,v);g+=`<circle cx=\"${a}\" cy=\"${b}\" r=\"2.6\" fill=\"${cols[p.pos]}\"/>`})});\n  return `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Radar skor PB-01.2 per kelompok\">${g}</svg><div class=\"legend\">${C.pemb.map(p=>`<span><i style=\"background:${cols[p.pos]}\"></i>P${p.pos+1} ${esc(p.name||'—')} · ${p.ok?fmtD(p.skor):'-'}</span>`).join('')}</div>`;\n}\n\n/* =========================================================\n   SHELL: header, sidebar\n   ========================================================= */\nfunction renderHeader(){\n  document.getElementById('hNama').textContent=S.paket.nama||'(Nama paket belum diisi)';\n  document.getElementById('hProyek').textContent=`${S.paket.proyek} · ID ${S.paket.idProyek} · ${S.paket.unit}`;\n  document.getElementById('hChips').innerHTML=`<div class=\"chip\"><b>HPS</b><span>${rp(C.hps)}</span></div><div class=\"chip\"><b>PPN</b><span>${pct(N(S.paket.ppn),0)}</span></div><div class=\"chip\"><b>Metode</b><span>${esc(S.paket.metode)}</span></div><div class=\"chip ${C.efis>0?'good':''}\"><b>Efisiensi</b><span>${C.win.ok?pct(C.efisPct):'–'}</span></div>`;\n}\nfunction renderSide(){\n  const a=(id,n,lbl,dot)=>`<a class=\"${VIEW===id?'on':''}\" data-go=\"${id}\" href=\"#${id}\">${n!=null?`<span class=\"n\">${n}</span>`:''}${dot!=null?`<span class=\"dot ${dot?'ok':''}\" aria-label=\"${dot?'memenuhi':'belum'}\"></span>`:''}<span class=\"lbl\">${lbl}</span></a>`;\n  document.getElementById('side').innerHTML=`<div class=\"nav\">${a('panduan',null,'Panduan input &amp; cetak')}${a('dash',null,'Dasbor')}</div><div class=\"navgrp\">Tahapan</div><div class=\"nav\">${TAHAP.map((t,i)=>a('s'+t.n,t.n,t.t,C.stage[i])).join('')}</div><div class=\"navgrp\">Arsip</div><div class=\"nav\">${a('rekap',null,'Rekapitulasi')}${a('acuan',null,'Acuan')}</div>\n  <div class=\"side-foot\"><b>${C.stageOk}</b> dari 12 tahap memenuhi<div class=\"meter\"><i style=\"width:${C.stageOk/12*100}%\"></i></div></div>`;\n}\n\n/* =========================================================\n   VIEWS\n   ========================================================= */\nfunction pageHead(k,t,d,extra){return `<div class=\"pagehead\"><div><div class=\"k\">${k}</div><h2>${t}</h2>${d?`<p>${d}</p>`:''}</div>${extra||''}</div>`}\nfunction alertsHtml(){if(!C.warn.length)return '<div class=\"alert ok\">Tidak ada peringatan. Seluruh status OK.</div>';return C.warn.map(w=>`<div class=\"alert ${w[0]==='bad'?'bad':''}\">${w[0]==='bad'?'✖':'⚠'} ${esc(w[1])}</div>`).join('')}\nfunction viewDash(){\n  const w=C.win;const st=C.siap;\n  return pageHead('Dasbor','Ringkasan pengadaan',`${esc(S.paket.metode)} · ${esc(S.paket.lokasi)} · ${esc(S.paket.waktu)}`)+`\n  <div class=\"kpis\">\n   <div class=\"kpi\"><div class=\"l\">HPS / APP (belum PPN)</div><div class=\"v\" id=\"kHps\">${rp(C.hps)}</div><div class=\"s\">${S.items.length} item · ${fmt(S.items.reduce((a,b)=>a+N(b.vol),0))} ${esc(S.items[0]?.satuan||'')}</div></div>\n   <div class=\"kpi\"><div class=\"l\">Harga final pemenang</div><div class=\"v\" id=\"kFinal\">${w.ok?rp(C.final):'–'}</div><div class=\"s\">${esc(w.ok?w.name:'Pemenang belum valid')}</div></div>\n   <div class=\"kpi\"><div class=\"l\">Harga final + PPN ${pct(N(S.paket.ppn),0)}</div><div class=\"v\" id=\"kPpn\">${w.ok?rp(C.finalPpn):'–'}</div><div class=\"s\">PPN ${rp(C.ppn)}</div></div>\n   <div class=\"kpi\"><div class=\"l\">Efisiensi terhadap HPS</div><div class=\"v\" id=\"kEf\">${w.ok?rp(C.efis):'–'}</div><div class=\"s\" id=\"kEfP\">${w.ok?pct(C.efisPct):''}</div></div>\n   <div class=\"kpi ${st?'ready':'notready'}\"><div class=\"l\">Status dokumen</div><div class=\"v\" id=\"kStatus\">${st?'SIAP CETAK':'BELUM SIAP'}</div><div class=\"s\">${C.stageOk} dari 12 tahap memenuhi</div></div>\n  </div>\n  <div class=\"grid2\"><div class=\"panel chart\"><h3>Penawaran awal → final per vendor <span class=\"pill acc\">Rp miliar</span></h3>${chartDumbbell()}</div>\n  <div class=\"panel chart\"><h3>% turun hasil negosiasi</h3>${chartTurun()}</div></div>\n  <div class=\"grid2\"><div class=\"panel chart radar\"><h3>Skor PB-01.2 per kelompok kriteria</h3>${chartRadar()}</div>\n  <div class=\"panel\"><h3>Pembanding &amp; rekomendasi</h3><div class=\"tbl-wrap\"><table class=\"t\"><tr><th>Pos</th><th>Vendor</th><th>Status</th><th class=\"r\">Final (Rp)</th><th class=\"r\">Skor</th><th class=\"r\">Rank</th></tr>${C.pemb.map(p=>`<tr><td>P${p.pos+1}</td><td>${esc(p.name||'—')}${w.ok&&p.v&&w.v.id===p.v.id?' <span class=\"pill acc\">Pemenang</span>':''}</td><td><span class=\"pill ${p.cls}\">${p.st}</span></td><td class=\"r num\">${p.final?fmt(p.final):'-'}</td><td class=\"r num\">${p.ok?fmtD(p.skor):'-'}</td><td class=\"r num\">${p.rank??'-'}</td></tr>`).join('')}</table></div>\n  <p class=\"note\">Rekomendasi sistem (harga final terendah): <b style=\"color:var(--fg)\">${esc(C.rek?C.rek.name:'-')}</b></p><div class=\"alerts\">${alertsHtml()}</div></div></div>\n  <div class=\"panel\" style=\"margin-top:14px\"><h3>Status tahapan <span class=\"pill ${C.stageOk===12?'ok':'warn'}\">${C.stageOk}/12</span></h3><div class=\"strip\">${TAHAP.map((t,i)=>`<button type=\"button\" class=\"${C.stage[i]?'ok':''}\" data-go=\"s${t.n}\" title=\"${esc(t.t)}\">${t.n}</button>`).join('')}</div><div class=\"strip-l\">${TAHAP.map(t=>`<span>${esc(t.t)}</span>`).join('')}</div></div>`;\n}\nfunction inp(path,label,opt={}){const v=getPath(S,path)??'';const cls=opt.full?'f full':'f';\n  if(opt.area)return `<label class=\"${cls}\">${label}<textarea data-b=\"${path}\" id=\"i_${path.replace(/\\W/g,'_')}\">${esc(v)}</textarea></label>`;\n  return `<label class=\"${cls}\">${label}<input data-b=\"${path}\" id=\"i_${path.replace(/\\W/g,'_')}\" ${opt.num?'type=\"number\" step=\"any\" data-t=\"num\"':opt.date?'type=\"date\"':'type=\"text\"'} ${opt.list?`list=\"${opt.list}\"`:''} value=\"${esc(v)}\"></label>`}\nfunction cellInp(path,opt={}){const v=getPath(S,path)??'';return `<td class=\"cell${opt.w?' w':''}\"><input aria-label=\"${esc(opt.label||path)}\" data-b=\"${path}\" id=\"c_${path.replace(/\\W/g,'_')}\" ${opt.num?'type=\"number\" step=\"any\" data-t=\"num\"':opt.date?'type=\"date\"':'type=\"text\"'} ${opt.list?`list=\"${opt.list}\"`:''} value=\"${esc(v)}\"></td>`}\nfunction vendorSelect(path,withAll,onlyPemb){const cur=getPath(S,path);const vs=onlyPemb?pembVendors():S.vendors;return `<select data-b=\"${path}\" data-rerender=\"1\" id=\"sel_${path.replace(/\\W/g,'_')}\">${withAll?`<option value=\"all\" ${cur==='all'?'selected':''}>Semua calon rekanan (umum)</option>`:''}${vs.map(v=>`<option value=\"${v.id}\" ${cur===v.id?'selected':''}>${esc(v.nama)}</option>`).join('')}</select>`}\nfunction previewBlock(n){return `<div class=\"preview\"><div class=\"pv-bar\"><span class=\"t\">Pratinjau dokumen A4</span><div class=\"row\">${[4,5,6,7,8].includes(n)?`<button class=\"btn sm\" type=\"button\" data-act=\"printAll\" data-n=\"${n}\">Cetak semua vendor</button>`:''}<button class=\"btn sm pri\" type=\"button\" data-act=\"printStage\" data-n=\"${n}\">Cetak dokumen ini</button></div></div><div class=\"pv-stage\" id=\"pvStage\"><div class=\"pv-scale\" id=\"pv\">${docsForStage(n)}</div></div></div>`}\nfunction stageWrap(n,form){const t=TAHAP[n-1];return pageHead(`Tahap ${n} dari 12 · <span class=\"pill ${C.stage[n-1]?'ok':'bad'}\" id=\"stPill\">${C.stage[n-1]?'Memenuhi':'Belum memenuhi'}</span>`,t.t,t.d,`<div class=\"row\">${n>1?`<button class=\"btn sm\" type=\"button\" data-go=\"s${n-1}\">← Tahap ${n-1}</button>`:''}${n<12?`<button class=\"btn sm\" type=\"button\" data-go=\"s${n+1}\">Tahap ${n+1} →</button>`:''}</div>`)+`<div class=\"work\"><div id=\"form\"><div class=\"panel hint\"><h3>Cara mengisi tahap ${n}</h3><ol>${HINT[n].map(h=>`<li>${h}</li>`).join('')}</ol></div>${form}</div>${previewBlock(n)}</div>`}\n\nfunction form1(){\n  const p='paket.';\n  const docRows=S.dok.map((d,i)=>`<tr><td class=\"num\">${i+1}</td><td style=\"min-width:180px\">${esc(DOKS[i].nama)}</td>${DOKS[i].numbered?cellInp(`dok.${i}.no`,{w:1,label:'Nomor '+DOKS[i].nama}):'<td class=\"cell w\"><span class=\"note\">tanpa nomor</span></td>'}${cellInp(`dok.${i}.tgl`,{date:1,label:'Tanggal'})}${DOKS[i].acara||DOKS[i].batas?cellInp(`dok.${i}.acara`,{date:1,label:'Tanggal acara'}):'<td></td>'}${DOKS[i].acara?cellInp(`dok.${i}.jam`,{label:'Waktu'})+cellInp(`dok.${i}.tempat`,{w:1,label:'Tempat'}):'<td></td><td></td>'}</tr>`).join('');\n  return `<div class=\"panel\"><h3>Paket pengadaan</h3><div class=\"fg\">${inp(p+'nama','Nama paket',{full:1})}${inp(p+'deskripsi','Deskripsi pengadaan',{full:1})}${inp(p+'material','Material / alat / pekerjaan')}${inp(p+'jenisPek','Jenis pekerjaan')}${inp(p+'metode','Metode pengadaan',{list:'dlMetode'})}${inp(p+'dana','Sumber pendanaan')}${inp(p+'waktu','Jangka waktu pelaksanaan')}${inp(p+'serah','Waktu penyerahan')}${inp(p+'asuransi','Asuransi',{full:1})}</div></div>\n  <div class=\"panel\"><h3>Proyek</h3><div class=\"fg\">${inp(p+'perusahaan','Nama perusahaan',{full:1})}${inp(p+'proyek','Nama proyek',{full:1})}${inp(p+'idProyek','ID proyek')}${inp(p+'kota','Kota lokasi (singkat)')}${inp(p+'unit','Business unit / unit kerja',{full:1})}${inp(p+'lokasi','Lokasi pekerjaan / Franco',{full:1})}${inp(p+'kotaTtd','Kota penandatanganan')}</div></div>\n  <div class=\"panel\"><h3>Kondisi komersial</h3><div class=\"fg\">${inp(p+'jenisKontrak','Jenis kontrak',{list:'dlKontrak'})}${inp(p+'progress','Pengakuan progress')}${inp(p+'um','Uang muka')}${inp(p+'ppn','Tarif PPN (desimal)',{num:1})}${inp(p+'bayar','Cara / syarat pembayaran',{full:1})}${inp(p+'bayarSingkat','Pembayaran (versi ringkas)')}</div></div>\n  <div class=\"panel\"><h3>Tim pengadaan</h3><div class=\"fg\">${inp('tim.ketua','Ketua')}${inp('tim.jabKetua','Jabatan ketua')}${inp('tim.sekretaris','Sekretaris')}${[0,1,2,3,4].map(i=>inp(`tim.anggota.${i}`,'Anggota '+(i+1))).join('')}${inp('tim.penetap','Pejabat penetap')}${inp('tim.jabPenetap1','Jabatan penetap (baris 1)')}${inp('tim.jabPenetap2','Jabatan penetap (baris 2)')}${inp(p+'tujuanUsulan','Tujuan laporan usulan')}${inp(p+'tembusan','Tembusan utama',{full:1})}</div></div>\n  <div class=\"panel\"><h3>Nomor &amp; tanggal 12 dokumen</h3>\n   <div class=\"row\" style=\"margin-bottom:10px\"><label class=\"f\" style=\"width:110px\">Nomor awal<input type=\"number\" data-b=\"nomor.awal\" data-t=\"num\" id=\"i_nomor_awal\" value=\"${esc(S.nomor.awal)}\"></label><label class=\"f\" style=\"flex:1;min-width:160px\">Akhiran<input type=\"text\" data-b=\"nomor.akhiran\" id=\"i_nomor_akhiran\" value=\"${esc(S.nomor.akhiran)}\"></label><button class=\"btn sm pri\" type=\"button\" data-act=\"autonomor\" style=\"align-self:flex-end\">Auto-nomor</button></div>\n   <p class=\"note\" style=\"margin:0 0 8px\">Format: <span class=\"mono\">021/UN-P/${esc(S.nomor.akhiran)}/X/2026</span> — nomor urut 3 digit, kode dokumen, akhiran, bulan Romawi dan tahun diambil dari tanggal surat.</p>\n   <div class=\"tbl-wrap\"><table class=\"t\"><tr><th>#</th><th>Dokumen</th><th>Nomor</th><th>Tanggal</th><th>Acara/batas</th><th>Waktu</th><th>Tempat</th></tr>${docRows}</table></div></div>`;\n}\nfunction form2(){\n  const list=S.vendors.map((v,i)=>`<tr><td class=\"num\">${i+1}</td>${VFIELDS.map(([k,l])=>cellInp(`vendors.${i}.${k}`,{w:k==='nama'||k==='alamat'||k==='kirim',label:l})).join('')}<td><button class=\"btn sm danger\" type=\"button\" data-act=\"delVendor\" data-i=\"${i}\" aria-label=\"Hapus vendor\">Hapus</button></td></tr>`).join('');\n  return `<div class=\"panel\"><h3>Pilih 3 vendor pembanding</h3>\n  ${[0,1,2].map(i=>`<div class=\"row\" style=\"margin-bottom:8px\"><label class=\"f\" style=\"flex:1;min-width:200px\">Pembanding ${i+1}<input list=\"dlVendor\" data-b=\"pemb.${i}\" id=\"i_pemb_${i}\" value=\"${esc(S.pemb[i]||'')}\"></label></div>`).join('')}\n  <div data-live=\"pembTable\"></div></div>\n  <div class=\"panel\"><h3>Database vendor <span class=\"row\"><button class=\"btn sm\" type=\"button\" data-act=\"addVendor\">+ Vendor</button><button class=\"btn sm\" type=\"button\" data-act=\"impCsv\">Impor CSV</button><button class=\"btn sm\" type=\"button\" data-act=\"expVendorCsv\">Ekspor CSV</button></span></h3>\n  <div class=\"tbl-wrap\"><table class=\"t\"><tr><th>#</th>${VFIELDS.map(f=>`<th>${f[1]}</th>`).join('')}<th></th></tr>${list}</table></div>\n  <p class=\"note\">Impor CSV memakai baris judul yang sama dengan kolom di atas (pemisah koma atau titik koma).</p></div>`;\n}\nconst live={\n  pembTable:()=>`<div class=\"tbl-wrap\"><table class=\"t\"><tr><th>Posisi</th><th>Status</th><th class=\"r\">Awal (Rp)</th><th class=\"r\">Final (Rp)</th><th class=\"r\">Peringkat</th></tr>${C.pemb.map(p=>`<tr><td>Pembanding ${p.pos+1}</td><td><span class=\"pill ${p.cls}\">${p.st}</span></td><td class=\"r num\">${p.awal?fmt(p.awal):'-'}</td><td class=\"r num\">${p.final?fmt(p.final):'-'}</td><td class=\"r num\">${p.rank??'-'}</td></tr>`).join('')}</table></div><p class=\"note\">Rekomendasi sistem (harga final terendah): <b style=\"color:var(--fg)\">${esc(C.rek?C.rek.name:'-')}</b></p>`,\n  hpsSum:()=>`<dl class=\"kv\"><dt>Jumlah HPS (belum PPN)</dt><dd>${rp(C.hps)}</dd><dt>PPN ${pct(N(S.paket.ppn),0)}</dt><dd>${rp(Math.round(C.hps*N(S.paket.ppn)))}</dd><dt>HPS + PPN</dt><dd>${rp(C.hpsPpn)}</dd></dl>`,\n  priceTot:()=>`<div class=\"tbl-wrap\"><table class=\"t\"><tr><th>Vendor</th><th class=\"r\">Total awal</th><th class=\"r\">Total final</th><th class=\"r\">% turun</th><th>Cek</th></tr>${S.vendors.map(v=>{const t=C.tot[v.id];const w=[];if(t.final>C.hps)w.push('<span class=\"pill warn\">&gt; HPS</span>');if(t.final>t.awal)w.push('<span class=\"pill bad\">final &gt; awal</span>');return `<tr><td>${esc(v.nama)}</td><td class=\"r num\">${fmt(t.awal)}</td><td class=\"r num\">${fmt(t.final)}</td><td class=\"r num\">${t.awal?fmtD((t.awal-t.final)/t.awal*100):'-'}%</td><td>${w.join(' ')||'<span class=\"pill ok\">OK</span>'}</td></tr>`}).join('')}</table></div>`,\n  evpTot:()=>`<dl class=\"kv\"><dt>Total bobot</dt><dd style=\"color:${Math.abs(C.bobotTot-100)<1e-9?'var(--ok)':'var(--bad)'}\">${fmtD(C.bobotTot,0)}</dd>${C.pemb.map(p=>`<dt>P${p.pos+1} ${esc(p.name||'—')}</dt><dd>${p.ok?fmtD(p.skor)+' · rank '+p.rankSkor:'-'}</dd>`).join('')}</dl>`,\n  winBox:()=>`<dl class=\"kv\"><dt>Status pemenang</dt><dd><span class=\"pill ${C.win.cls}\">${C.win.st}</span></dd><dt>Rekomendasi (final terendah)</dt><dd>${esc(C.rek?C.rek.name:'-')}</dd><dt>Skor tertinggi PB-01.2</dt><dd>${esc(C.topSkor?C.topSkor.name:'-')}</dd><dt>Harga final</dt><dd>${C.win.ok?rp(C.final):'-'}</dd><dt>PPN</dt><dd>${C.win.ok?rp(C.ppn):'-'}</dd><dt>Final + PPN</dt><dd>${C.win.ok?rp(C.finalPpn):'-'}</dd><dt>Efisiensi</dt><dd>${C.win.ok?rp(C.efis)+' ('+pct(C.efisPct)+')':'-'}</dd><dt>Status dokumen</dt><dd><span class=\"pill ${C.siap?'ok':'bad'}\">${C.siap?'SIAP CETAK':'BELUM SIAP'}</span></dd></dl><p class=\"note\">Terbilang: <i>${terbilang(C.finalPpn)}</i></p><div class=\"alerts\">${alertsHtml()}</div>`,\n  sanggah:()=>`<p class=\"note\">Batas sanggah: <b style=\"color:var(--fg)\">${hariTgl(addDays(S.dok[9].tgl,2))}</b> (2 hari kalender setelah pengumuman).</p>`,\n  klarHarga:()=>{const v=C.pemb[S.sel.klar]?.v;if(!v)return '';const t=C.tot[v.id];return `<dl class=\"kv\"><dt>Penawaran awal</dt><dd>${rp(t.awal)}</dd><dt>Penawaran akhir</dt><dd>${rp(t.final)}</dd><dt>Turun</dt><dd>${t.awal?pct((t.awal-t.final)/t.awal):'-'}</dd></dl>${t.final>t.awal?'<div class=\"alert bad\">✖ Harga akhir lebih tinggi dari penawaran awal.</div>':''}${t.final>C.hps?'<div class=\"alert\">⚠ Harga akhir melebihi HPS.</div>':''}`}\n};\nfunction form3(){\n  const items=S.items.map((it,i)=>`<tr><td class=\"num\">${i+1}</td>${cellInp(`items.${i}.uraian`,{w:1,label:'Uraian'})}${cellInp(`items.${i}.spek`,{w:1,label:'Spesifikasi'})}${cellInp(`items.${i}.satuan`,{label:'Satuan'})}${cellInp(`items.${i}.vol`,{num:1,label:'Volume'})}${cellInp(`items.${i}.hps`,{num:1,label:'Harsat HPS'})}<td><button class=\"btn sm danger\" type=\"button\" data-act=\"delItem\" data-i=\"${i}\">Hapus</button></td></tr>`).join('');\n  const price=S.items.map((it,i)=>`<div style=\"margin-top:12px\"><div class=\"note\" style=\"margin:0 0 6px;color:var(--fg)\">Item ${i+1}: ${esc(it.uraian||'—')} <span class=\"mono\">(HPS ${fmt(it.hps)}/${esc(it.satuan)})</span></div><div class=\"tbl-wrap\"><table class=\"t\"><tr><th>Vendor</th><th>Harsat awal</th><th>Harsat final</th></tr>${S.vendors.map(v=>`<tr><td>${esc(v.nama)}</td>${cellInp(`items.${i}.awal.${v.id}`,{num:1,label:'Awal '+v.nama})}${cellInp(`items.${i}.final.${v.id}`,{num:1,label:'Final '+v.nama})}</tr>`).join('')}</table></div></div>`).join('');\n  return `<div class=\"panel\"><h3>Item &amp; HPS <button class=\"btn sm\" type=\"button\" data-act=\"addItem\">+ Item</button></h3><div class=\"tbl-wrap\"><table class=\"t\"><tr><th>#</th><th>Uraian</th><th>Spesifikasi</th><th>Satuan</th><th>Volume</th><th>Harsat HPS</th><th></th></tr>${items}</table></div><div style=\"margin-top:10px\" data-live=\"hpsSum\"></div></div>\n  <div class=\"panel\"><h3>Harga satuan penawaran (Rp, belum PPN)</h3>${price}</div>\n  <div class=\"panel\"><h3>Total per vendor</h3><div data-live=\"priceTot\"></div></div>`;\n}\nfunction form4(){return `<div class=\"panel\"><h3>Undangan</h3><div class=\"fg\"><label class=\"f full\">Ditujukan kepada${vendorSelect('sel.und',true)}</label>${inp('dok.0.no','Nomor surat',{full:1})}${inp('dok.0.tgl','Tanggal surat',{date:1})}</div><p class=\"note\">Pilih \"Semua calon rekanan\" untuk satu surat umum, atau satu vendor untuk surat bernama. \"Cetak semua vendor\" membuat satu surat untuk tiap vendor di database.</p></div>`}\nfunction form5(){return `<div class=\"panel\"><h3>Undangan aanwijzing</h3><div class=\"fg\"><label class=\"f full\">Ditujukan kepada${vendorSelect('sel.unda',true)}</label>${inp('dok.1.no','Nomor surat',{full:1})}${inp('dok.1.tgl','Tanggal surat',{date:1})}${inp('dok.1.acara','Tanggal rapat',{date:1})}${inp('dok.1.jam','Waktu')}${inp('dok.1.tempat','Tempat',{full:1})}</div></div>`}\nfunction form6(){\n  const rows=AAN_ROWS.map((r,i)=>`<div class=\"aanrow\"><div class=\"h\">${r.sec} · ${esc(r.h)}</div><div class=\"chk\">${r.o.map((o,j)=>`<label><input type=\"checkbox\" data-chk=\"${i}:${j}\" id=\"chk_${i}_${j}\" ${(S.aan.sel[i]||[]).includes(j)?'checked':''}>${esc(o)}</label>`).join('')}</div></div>`).join('');\n  return `<div class=\"panel\"><h3>BA Aanwijzing</h3><div class=\"fg\"><label class=\"f full\">Calon penyedia<select data-b=\"aan.untuk\" data-rerender=\"1\" id=\"sel_aan_untuk\"><option value=\"all\" ${S.aan.untuk==='all'?'selected':''}>Seluruh calon penyedia (umum)</option>${S.vendors.map(v=>`<option value=\"${v.id}\" ${S.aan.untuk===v.id?'selected':''}>${esc(v.nama)}</option>`).join('')}</select></label>${inp('dok.2.tgl','Tanggal BA',{date:1})}</div></div>\n  <div class=\"panel\"><h3>Checklist persyaratan</h3>${rows}<p class=\"note\">Setiap baris wajib memiliki minimal satu pilihan agar tahap ini memenuhi.</p></div>\n  <div class=\"panel\"><h3>Catatan tambahan</h3>${inp('aan.catatan','Catatan (tercetak di bagian I)',{area:1,full:1})}</div>`;\n}\nfunction form7(){return `<div class=\"panel\"><h3>Surat permintaan penawaran</h3><div class=\"fg\"><label class=\"f full\">Vendor${vendorSelect('sel.rfq',false)}</label>${inp('dok.3.no','Nomor dasar (ditambah .no urut vendor)',{full:1})}${inp('dok.3.tgl','Tanggal surat',{date:1})}${inp('dok.3.acara','Batas pemasukan penawaran',{date:1})}${inp('syaratRFQ','Syarat-syarat penawaran (bagian D)',{area:1,full:1})}</div><p class=\"note\">Nomor surat vendor terpilih: <span class=\"mono\" data-live=\"rfqNo\"></span></p></div>`}\nlive.rfqNo=()=>esc(rfqNo(C.vById(S.sel.rfq)));\nfunction form8(){\n  const v=C.pemb[S.sel.klar]?.v;const k=klarOf(v);\n  const pair=(a,l)=>`<tr><td>${l}</td>${cellInp(`klar.${v.id}.${a}_t`,{w:1,label:l+' tender'})}${cellInp(`klar.${v.id}.${a}_u`,{w:1,label:l+' usulan'})}</tr>`;\n  return `<div class=\"panel\"><h3>Vendor yang diklarifikasi</h3><div class=\"seg\" role=\"tablist\">${C.pemb.map((p,i)=>`<button type=\"button\" class=\"${S.sel.klar===i?'on':''}\" data-act=\"klarSel\" data-i=\"${i}\">P${i+1} ${esc((p.name||'—').split(',')[0])}</button>`).join('')}</div>\n  <div class=\"fg\" style=\"margin-top:10px\">${inp('dok.4.no','Nomor undangan',{full:1})}${inp('dok.4.tgl','Tanggal undangan',{date:1})}${inp('dok.4.acara','Tanggal klarifikasi',{date:1})}${inp('dok.4.jam','Waktu')}${inp('dok.4.tempat','Tempat')}${inp('dok.5.tgl','Tanggal BA PB-01B-2',{date:1})}</div></div>\n  ${v?`<div class=\"panel\"><h3>Tender vs usulan rekanan</h3><div class=\"tbl-wrap\"><table class=\"t\"><tr><th>Uraian</th><th>Persyaratan tender</th><th>Usulan rekanan</th></tr>${pair('mat','Material')}${pair('spek','Spesifikasi')}${pair('sat','Satuan')}${pair('ahli','Tenaga ahli')}${pair('metode','Metode kerja')}${pair('alat','Alat/peralatan')}</table></div></div>\n  <div class=\"panel\"><h3>Harga awal vs akhir</h3><div data-live=\"klarHarga\"></div><p class=\"note\">Harga satuan diubah di Tahap 3.</p></div>\n  <div class=\"panel\"><h3>Catatan</h3>${inp(`klar.${v.id}.catatan`,'Catatan khusus',{area:1,full:1})}</div>`:'<div class=\"panel\"><div class=\"alert bad\">Pembanding ini belum valid. Perbaiki di Tahap 2.</div></div>'}`;\n}\nfunction form9(){return `<div class=\"panel\"><h3>Evaluasi harga final</h3><div class=\"fg\">${inp('dok.6.tgl','Tanggal evaluasi',{date:1})}</div><div style=\"margin-top:10px\" data-live=\"pembTable\"></div></div><div class=\"panel\"><h3>Ringkasan</h3><div data-live=\"winBox\"></div></div>`}\nfunction form10(){\n  const pb=C.pemb;\n  const rows=KRIT.map((k,i)=>`<tr><td><span class=\"note\" style=\"margin:0\">${k.g}</span> ${esc(k.label)}</td>${cellInp(`bobot.${i}`,{num:1,label:'Bobot '+k.label})}${pb.map(p=>p.ok?(k.auto?`<td class=\"r num\" title=\"MIN(1; HPS/final)\">${fmtD(C.nilaiOf(p.v.id,i),4)}</td>`:cellInp(`nilai.${p.v.id}.${i}`,{num:1,label:'Nilai '+k.label+' '+p.name})):'<td>-</td>').join('')}</tr>`).join('');\n  return `<div class=\"panel\"><h3>Skor PB-01.2 <span class=\"pill acc\">nilai 0–1</span></h3><div class=\"fg\" style=\"margin-bottom:10px\">${inp('dok.7.tgl','Tanggal evaluasi',{date:1})}</div>\n  <div class=\"tbl-wrap\"><table class=\"t\"><tr><th>Kriteria</th><th>Bobot</th>${pb.map(p=>`<th>P${p.pos+1} ${esc((p.name||'—').split(',')[0])}</th>`).join('')}</tr>${rows}</table></div><p class=\"note\">Nilai harga dihitung otomatis = MIN(1; HPS / harga final). Skor = bobot × nilai.</p></div>\n  <div class=\"panel\"><h3>Hasil</h3><div data-live=\"evpTot\"></div></div>`;\n}\nfunction form11(){\n  return `<div class=\"panel\"><h3>Penetapan pemenang</h3><div class=\"fg\"><label class=\"f full\">Vendor pemenang (harus salah satu pembanding)<select data-b=\"pemenang\" id=\"sel_pemenang\"><option value=\"\">— pilih —</option>${C.pemb.filter(p=>p.name).map(p=>`<option ${S.pemenang===p.name?'selected':''}>${esc(p.name)}</option>`).join('')}${S.pemenang&&!C.pemb.some(p=>p.name===S.pemenang)?`<option selected>${esc(S.pemenang)}</option>`:''}</select></label></div>\n  <div class=\"row\" style=\"margin-top:8px\"><button class=\"btn sm\" type=\"button\" data-act=\"useRek\">Gunakan rekomendasi sistem</button></div></div>\n  <div class=\"panel\"><h3>Ringkasan &amp; validasi</h3><div data-live=\"winBox\"></div></div>\n  <div class=\"panel\"><h3>Dokumen</h3><div class=\"fg\">${inp('dok.8.no','Nomor BA PB-10',{full:1})}${inp('dok.8.tgl','Tanggal BA',{date:1})}<span></span>${inp('dok.9.no','Nomor pengumuman',{full:1})}${inp('dok.9.tgl','Tanggal pengumuman',{date:1})}${inp('catatanPB10','Lampiran lain-lain (opsional)',{full:1})}</div><div data-live=\"sanggah\"></div></div>`;\n}\nfunction form12(){return `<div class=\"panel\"><h3>Laporan usulan</h3><div class=\"fg\">${inp('dok.10.no','Nomor laporan',{full:1})}${inp('dok.10.tgl','Tanggal',{date:1})}${inp('paket.tujuanUsulan','Kepada Yth.')}</div></div>\n  <div class=\"panel\"><h3>Surat Penetapan Pemenang (SPPBJ)</h3><div class=\"fg\">${inp('dok.11.no','Nomor SPPBJ',{full:1})}${inp('dok.11.tgl','Tanggal',{date:1})}${inp('tim.penetap','Pejabat penetap')}${inp('tim.jabPenetap1','Jabatan (baris 1)')}${inp('tim.jabPenetap2','Jabatan (baris 2)')}</div></div>\n  <div class=\"panel\"><h3>Ringkasan</h3><div data-live=\"winBox\"></div></div>`}\n\nfunction viewRekap(){\n  return pageHead('Arsip','Rekapitulasi paket','Semua paket yang disimpan dengan tombol \"Simpan rekap\". Muat untuk melanjutkan, atau ekspor ke CSV.',`<div class=\"row\"><button class=\"btn sm\" type=\"button\" data-act=\"expJson\">Ekspor JSON paket aktif</button><button class=\"btn sm\" type=\"button\" data-act=\"impJson\">Impor JSON</button><button class=\"btn sm\" type=\"button\" data-act=\"expRekapCsv\">Ekspor rekap CSV</button><button class=\"btn sm\" type=\"button\" data-act=\"newPaket\">Paket baru (kosong)</button><button class=\"btn sm\" type=\"button\" data-act=\"demo\">Muat data demo</button></div>`)+\n  `<div class=\"panel\"><h3>Daftar paket <span class=\"pill ${DBREADY?'ok':'warn'}\" id=\"dbPill\">${DBREADY?'Database artefak':'Penyimpanan lokal peramban'}</span></h3><div id=\"rekapList\">${rekapTable()}</div></div>`;\n}\nfunction rekapTable(){\n  if(!REKAP.length)return `<p class=\"note\">Belum ada paket tersimpan. Tekan <b style=\"color:var(--fg)\">Simpan rekap</b> di bagian atas untuk menyimpan paket aktif.</p>`;\n  const tot=REKAP.reduce((a,r)=>({hps:a.hps+N(r.hps),final:a.final+N(r.final),efis:a.efis+N(r.efisiensi)}),{hps:0,final:0,efis:0});\n  return `<div class=\"tbl-wrap\"><table class=\"t\"><tr><th>Paket</th><th>Proyek</th><th>Pemenang</th><th class=\"r\">HPS</th><th class=\"r\">Final</th><th class=\"r\">Final+PPN</th><th class=\"r\">Efisiensi</th><th>Status</th><th>Diperbarui</th><th></th></tr>${REKAP.map(r=>`<tr><td>${esc(r.namaPaket)}</td><td>${esc(r.idProyek)}</td><td>${esc(r.pemenang||'-')}</td><td class=\"r num\">${fmt(r.hps)}</td><td class=\"r num\">${fmt(r.final)}</td><td class=\"r num\">${fmt(r.finalPpn)}</td><td class=\"r num\">${fmt(r.efisiensi)} (${fmtD(N(r.efisiensiPct)*100)}%)</td><td><span class=\"pill ${r.status==='SIAP CETAK'?'ok':'bad'}\">${esc(r.status)}</span> <span class=\"note\">${r.tahap}/12</span></td><td class=\"num\" style=\"white-space:nowrap\">${esc(r.updatedAt?new Date(r.updatedAt).toLocaleString('id-ID',{dateStyle:'short',timeStyle:'short'}):'')}</td><td style=\"white-space:nowrap\"><button class=\"btn sm\" type=\"button\" data-act=\"loadRekap\" data-id=\"${esc(r.id)}\">Muat</button> <span data-del=\"${esc(r.id)}\"><button class=\"btn sm danger\" type=\"button\" data-act=\"askDel\" data-id=\"${esc(r.id)}\">Hapus</button></span></td></tr>`).join('')}\n  <tr><td colspan=\"3\"><b>Total ${REKAP.length} paket</b></td><td class=\"r num\"><b>${fmt(tot.hps)}</b></td><td class=\"r num\"><b>${fmt(tot.final)}</b></td><td></td><td class=\"r num\"><b>${fmt(tot.efis)}</b></td><td colspan=\"3\"></td></tr></table></div>`;\n}\nfunction viewAcuan(){\n  return pageHead('Referensi','Acuan perhitungan & bobot','Ketentuan yang dipakai PBJ Studio untuk menghitung dan memvalidasi dokumen.')+`\n  <div class=\"grid2\"><div class=\"panel\"><h3>Bobot PB-01.2 (total ${fmtD(KRIT.reduce((a,k)=>a+k.b,0),0)})</h3><div class=\"tbl-wrap\"><table class=\"t\"><tr><th>Kel.</th><th>Kriteria</th><th class=\"r\">Bobot</th><th>Pedoman nilai</th></tr>${KRIT.map(k=>`<tr><td>${k.g}</td><td>${esc(k.label)}</td><td class=\"r num\">${k.b}</td><td style=\"font-size:12px;color:var(--muted)\">${esc(k.ket)}</td></tr>`).join('')}</table></div></div>\n  <div><div class=\"panel\"><h3>Rumus</h3><dl class=\"kv\" style=\"grid-template-columns:1fr\"><dt>HPS</dt><dd style=\"text-align:left\">Σ (volume × harsat HPS)</dd><dt>Harga final vendor</dt><dd style=\"text-align:left\">Σ (volume × harsat final)</dd><dt>PPN</dt><dd style=\"text-align:left\">ROUND(harga final × 11%)</dd><dt>Efisiensi</dt><dd style=\"text-align:left\">HPS − harga final; % = efisiensi / HPS</dd><dt>Nilai harga PB-01.2</dt><dd style=\"text-align:left\">MIN(1; HPS / harga final)</dd><dt>Skor</dt><dd style=\"text-align:left\">Σ bobot × nilai (0–1)</dd><dt>PB-10 efisiensi</dt><dd style=\"text-align:left\">(HPS + PPN) − (final + PPN)</dd></dl></div>\n  <div class=\"panel\"><h3>Validasi</h3><ul style=\"margin:0;padding-left:18px;font-size:13px;color:var(--muted)\"><li>Status pembanding: Belum dipilih / Tidak ada di DB / Duplikat / OK.</li><li>Peringkat dari harga final terendah; rekomendasi = harga final terendah.</li><li>Pemenang wajib salah satu pembanding; peringatan bila berbeda dengan rekomendasi atau skor tertinggi.</li><li>SIAP CETAK hanya jika 3 pembanding dan pemenang berstatus OK.</li><li>Peringatan bila final &gt; HPS atau final &gt; awal.</li><li>Masa sanggah 2 hari kalender sejak pengumuman.</li></ul></div>\n  <div class=\"panel\"><h3>Format nomor surat</h3><p class=\"note mono\" style=\"color:var(--fg)\">NNN/KODE/${esc(S.nomor.akhiran)}/BULAN-ROMAWI/TAHUN</p><div class=\"tbl-wrap\" style=\"margin-top:8px\"><table class=\"t\"><tr><th>Dokumen</th><th>Kode</th></tr>${DOKS.filter(d=>d.numbered).map(d=>`<tr><td>${esc(d.nama)}</td><td class=\"mono\">${d.kode}</td></tr>`).join('')}</table></div><p class=\"note\">RFQ per vendor diberi sisipan nomor urut vendor, mis. 025.1/RFQ/…</p></div></div></div>`;\n}\n\n/* =========================================================\n   RENDER\n   ========================================================= */\n\nconst HINT={\n 1:['Isi <b>Paket pengadaan</b>, <b>Proyek</b> dan <b>Kondisi komersial</b> sesuai DB_MASTER (nama paket, lokasi Franco, jangka waktu, jenis kontrak, cara bayar).','Isi <b>Tim pengadaan</b>: ketua, sekretaris, 5 anggota, pejabat penetap.','Isi <b>tanggal</b> 12 dokumen (dan tanggal/waktu/tempat acara untuk aanwijzing, RFQ, nego).','Isi <b>Nomor awal</b> lalu tekan <b>Auto-nomor</b>, atau ketik nomor manual di kolom Nomor.'],\n 2:['Lengkapi <b>Database vendor</b> (nama, alamat, pimpinan, NPWP, WAVE, plant, dst.), atau tekan <b>Impor CSV</b>.','Ketik atau pilih <b>3 vendor pembanding</b>. Status harus <span class=\"pill ok\">OK</span> untuk ketiganya.','Nama harus sama persis dengan database; status \"Tidak ada di DB\" atau \"Duplikat\" membuat dokumen belum siap cetak.'],\n 3:['Isi item: <b>uraian, spesifikasi, satuan, volume, harsat HPS</b>. Tambah baris dengan <b>+ Item</b>.','Isi <b>harsat awal</b> (dari surat penawaran) dan <b>harsat final</b> (hasil BA nego) untuk setiap vendor.','Periksa tabel <b>Total per vendor</b>: label \"&gt; HPS\" atau \"final &gt; awal\" adalah peringatan.'],\n 4:['Pilih penerima: satu surat umum atau satu vendor.','Periksa nomor dan tanggal surat.','Tekan <b>Cetak dokumen ini</b>, atau <b>Cetak semua vendor</b> untuk satu surat per vendor.'],\n 5:['Pilih penerima undangan.','Isi tanggal rapat, waktu dan tempat aanwijzing.','Cetak.'],\n 6:['Pilih calon penyedia (umum atau per vendor).','Centang ketentuan yang disepakati pada setiap baris checklist (jenis kontrak, harga, Loco/Franco, pajak, pembayaran, UM, jaminan, dst.). Yang tidak dicentang tercetak dicoret.','Isi catatan tambahan bila perlu, lalu cetak.'],\n 7:['Pilih vendor penerima RFQ. Nomor otomatis diberi sisipan nomor urut vendor.','Isi batas pemasukan penawaran dan syarat-syarat penawaran.','Cetak per vendor, atau <b>Cetak semua vendor</b>.'],\n 8:['Pilih pembanding (P1/P2/P3) di tombol atas.','Isi jadwal undangan nego dan tanggal BA.','Isi kolom <b>Persyaratan tender</b> vs <b>Usulan rekanan</b> (material, spesifikasi, tenaga ahli, metode, alat) dan catatan khusus. Harga awal/akhir diambil dari Tahap 3.','Cetak undangan + BA PB-01B-2 untuk vendor ini, atau semua pembanding sekaligus.'],\n 9:['Isi tanggal evaluasi. Tabel PB-01A terisi otomatis dari Tahap 3 (HPS, harga final, PPN, total, peringkat).','Periksa peringatan di Ringkasan, lalu cetak.'],\n 10:['Isi <b>nilai 0–1</b> setiap kriteria untuk 3 pembanding (lihat pedoman di menu Acuan).','Nilai harga dihitung otomatis = MIN(1; HPS/final). Total bobot harus 100.','Cetak PB-01.2.'],\n 11:['Pilih <b>vendor pemenang</b> (harus salah satu pembanding) atau tekan <b>Gunakan rekomendasi sistem</b>.','Pastikan status <span class=\"pill ok\">SIAP CETAK</span>.','Isi nomor/tanggal BA PB-10 dan Pengumuman. Batas sanggah 2 hari kalender dihitung otomatis.','Cetak BA PB-10 + Pengumuman.'],\n 12:['Isi nomor/tanggal Laporan Usulan dan SPPBJ, serta pejabat penetap.','Cetak Laporan Usulan + SPPBJ.','Tekan <b>Simpan rekap</b> di atas untuk mengarsipkan paket.']\n};\nfunction viewPanduan(){\n  const grp=[['Persiapan data',[1,2,3]],['Undangan & penjelasan',[4,5,6]],['Penawaran & negosiasi',[7,8]],['Evaluasi',[9,10]],['Penetapan pemenang',[11,12]]];\n  return pageHead('Panduan','Cara input sampai dokumen siap cetak','Isi data master satu kali di Tahap 1–3. Semua dokumen Tahap 4–12 terisi otomatis dari data tersebut; Bapak hanya melengkapi isian khusus tiap dokumen lalu mencetak.',`<div class=\"row\"><button class=\"btn pri\" type=\"button\" data-go=\"s1\">Mulai dari Tahap 1 →</button><button class=\"btn\" type=\"button\" data-act=\"newPaket\">Paket baru (kosong)</button></div>`)+\n  `<div class=\"flow\">${grp.map(([g,ns])=>`<div class=\"panel\"><h3>${g}</h3>${ns.map(n=>`<div class=\"fstep\"><button type=\"button\" class=\"fnum ${C.stage[n-1]?'ok':''}\" data-go=\"s${n}\">${n}</button><div><b>${TAHAP[n-1].t}</b><ol>${HINT[n].map(h=>`<li>${h}</li>`).join('')}</ol></div></div>`).join('')}</div>`).join('')}</div>\n  <div class=\"grid2\" style=\"margin-top:14px\"><div class=\"panel\"><h3>Cara mencetak</h3><ol class=\"plist\">\n  <li>Buka tahap yang dokumennya ingin dicetak; pratinjau A4 di kanan sudah sama dengan hasil cetak.</li>\n  <li>Tekan <b>Cetak dokumen ini</b> (tahap aktif) atau tombol <b>Cetak</b> di atas (di Dasbor: berkas lengkap 12 tahap).</li>\n  <li><b>Jika aplikasi dibuka sebagai file di Chrome/Edge</b>: dialog print langsung terbuka. Pilih printer atau <i>Save as PDF</i>, kertas <b>A4</b>, margin <b>None/Tidak ada</b>, skala <b>100%</b>.</li>\n  <li><b>Jika dibuka di Claude</b>: tombol cetak menyimpan berkas .html siap cetak. Buka berkas itu, dialog print terbuka otomatis.</li>\n  <li>PB-01A dan PB-01.2 otomatis landscape; dokumen lain portrait.</li>\n  <li>Cap merah \"DRAF – BELUM SIAP CETAK\" muncul selama status belum SIAP CETAK.</li></ol></div>\n  <div class=\"panel\"><h3>Status saat ini</h3><dl class=\"kv\"><dt>Tahap memenuhi</dt><dd>${C.stageOk} / 12</dd><dt>Status dokumen</dt><dd><span class=\"pill ${C.siap?'ok':'bad'}\">${C.siap?'SIAP CETAK':'BELUM SIAP'}</span></dd><dt>Pemenang</dt><dd>${esc(C.win.ok?C.win.name:'-')}</dd><dt>Final + PPN</dt><dd>${C.win.ok?rp(C.finalPpn):'-'}</dd></dl><div class=\"alerts\">${alertsHtml()}</div>\n  <h3 style=\"margin-top:14px\">Simpan &amp; pindah data</h3><ul class=\"plist\"><li>Isian tersimpan otomatis di perangkat ini.</li><li><b>Simpan rekap</b> mengarsipkan paket ke menu Rekapitulasi.</li><li>Menu Rekapitulasi: ekspor/impor JSON (seluruh paket) dan CSV.</li></ul></div></div>`;\n}\n\nconst FORMS={1:form1,2:form2,3:form3,4:form4,5:form5,6:form6,7:form7,8:form8,9:form9,10:form10,11:form11,12:form12};\nfunction render(){\n  C=compute();renderHeader();renderSide();\n  const m=document.getElementById('main');\n  if(VIEW==='dash')m.innerHTML=viewDash();\n  else if(VIEW==='rekap')m.innerHTML=viewRekap();\n  else if(VIEW==='acuan')m.innerHTML=viewAcuan();\n  else if(VIEW==='panduan')m.innerHTML=viewPanduan();\n  else{const n=+VIEW.slice(1);m.innerHTML=stageWrap(n,FORMS[n]())}\n  fillLive();fitPreview();\n}\nfunction refresh(){\n  C=compute();renderHeader();renderSide();\n  if(VIEW.startsWith('s')){const n=+VIEW.slice(1);const pv=document.getElementById('pv');if(pv)pv.innerHTML=docsForStage(n);const sp=document.getElementById('stPill');if(sp){sp.className='pill '+(C.stage[n-1]?'ok':'bad');sp.textContent=C.stage[n-1]?'Memenuhi':'Belum memenuhi'}fillLive();\n    if(n===10){document.querySelectorAll('#form td[title]').forEach((td,ix)=>{});const f=document.getElementById('form');/* nilai harga otomatis */const pb=C.pemb;const autoIdx=KRIT.findIndex(k=>k.auto);const tr=f.querySelectorAll('table.t tr')[autoIdx+1];if(tr){let c=2;pb.forEach(p=>{const td=tr.children[c++];if(td&&p.ok&&td.classList.contains('r'))td.textContent=fmtD(C.nilaiOf(p.v.id,autoIdx),4)})}}\n  }\n  saveDraft();\n}\nfunction fillLive(){document.querySelectorAll('[data-live]').forEach(el=>{const f=live[el.dataset.live];if(f)el.innerHTML=f()})}\nfunction fitPreview(){const st=document.getElementById('pvStage');if(!st)return;const pv=document.getElementById('pv');const land=pv.querySelector('.paper.land');const pw=land?1123:794;const z=Math.min(1,(st.clientWidth-30)/pw);pv.style.setProperty('--z',Math.max(.3,z).toFixed(3))}\naddEventListener('resize',()=>fitPreview());\n\n/* =========================================================\n   EVENTS\n   ========================================================= */\nfunction go(id){VIEW=id;try{sessionStorage.setItem('pbj-view',id)}catch(e){}render();document.getElementById('main').scrollTop=0;window.scrollTo(0,0)}\ndocument.addEventListener('click',e=>{\n  const g=e.target.closest('[data-go]');if(g){e.preventDefault();go(g.dataset.go);return}\n  const b=e.target.closest('[data-act]');if(!b)return;\n  const a=b.dataset.act;\n  if(a==='addVendor'){const id='v'+Date.now().toString(36);S.vendors.push({id,nama:'Vendor Baru '+(S.vendors.length+1),alamat:'',pimpinan:'',jabatan:'Direktur',email:'',telp:'',npwp:'',kualifikasi:'',wave:'',plant:'',schedul:'',kirim:'',approval:''});S.nilai[id]=KRIT.map(k=>k.auto?null:0);render();saveDraft()}\n  else if(a==='delVendor'){const v=S.vendors[+b.dataset.i];S.vendors.splice(+b.dataset.i,1);if(v){delete S.nilai[v.id];delete S.klar[v.id];S.items.forEach(it=>{delete it.awal[v.id];delete it.final[v.id]})}render();saveDraft()}\n  else if(a==='addItem'){S.items.push({uraian:'',spek:'',satuan:'',vol:0,hps:0,awal:{},final:{}});render();saveDraft()}\n  else if(a==='delItem'){S.items.splice(+b.dataset.i,1);render();saveDraft()}\n  else if(a==='autonomor'){autoNomor();render();saveDraft();toast('Nomor surat dibuat ulang dari nomor awal '+String(S.nomor.awal).padStart(3,'0'))}\n  else if(a==='klarSel'){S.sel.klar=+b.dataset.i;render();saveDraft()}\n  else if(a==='useRek'){if(C.rek){S.pemenang=C.rek.name;render();saveDraft();toast('Pemenang diisi dengan rekomendasi sistem')}}\n  else if(a==='printStage')printDocs(docsForStage(+b.dataset.n),`Tahap ${b.dataset.n} - ${TAHAP[+b.dataset.n-1].t}`);\n  else if(a==='printAll')printDocs(docsForStage(+b.dataset.n,true),`Tahap ${b.dataset.n} - semua vendor`);\n  else if(a==='expJson')saveFile(fileBase()+'.json',JSON.stringify(S,null,1));\n  else if(a==='impJson')document.getElementById('fileJson').click();\n  else if(a==='impCsv')document.getElementById('fileCsv').click();\n  else if(a==='expVendorCsv')saveFile(fileBase()+'-vendor-penawaran.csv',vendorCsv());\n  else if(a==='expRekapCsv')saveFile('rekap-pengadaan.csv',rekapCsv());\n  else if(a==='newPaket'){S=blankState();VIEW='s1';render();saveDraft();toast('Paket baru dibuat. Isi mulai dari Tahap 1.')}\n  else if(a==='demo'){S=demoState();render();saveDraft();toast('Data demo dimuat')}\n  else if(a==='loadRekap'){const r=REKAP.find(x=>x.id===b.dataset.id);if(r&&r.state){S=normalize(JSON.parse(JSON.stringify(r.state)));VIEW='dash';render();saveDraft();toast('Paket dimuat: '+r.namaPaket)}}\n  else if(a==='askDel'){const sp=b.parentElement;sp.innerHTML=`<span class=\"confirm\">Hapus? <button class=\"btn sm danger\" type=\"button\" data-act=\"doDel\" data-id=\"${esc(b.dataset.id)}\">Ya</button><button class=\"btn sm\" type=\"button\" data-act=\"noDel\">Batal</button></span>`}\n  else if(a==='noDel'){document.getElementById('rekapList').innerHTML=rekapTable()}\n  else if(a==='doDel'){delRekap(b.dataset.id)}\n});\nfunction onField(e){\n  const t=e.target;\n  if(t.dataset.chk){const [i,j]=t.dataset.chk.split(':').map(Number);const s=new Set(S.aan.sel[i]||[]);t.checked?s.add(j):s.delete(j);S.aan.sel[i]=[...s].sort();refresh();return}\n  const p=t.dataset.b;if(!p)return;\n  let v=t.value;if(t.dataset.t==='num')v=v===''?'':Number(v);\n  setPath(S,p,v);\n  if(t.dataset.rerender&&e.type==='change'){render();saveDraft();return}\n  refresh();\n}\ndocument.addEventListener('input',onField);\ndocument.addEventListener('change',e=>{if(e.target.matches('select,input[type=checkbox],input[type=date]'))onField(e)});\ndocument.getElementById('btnPrint').addEventListener('click',()=>{\n  if(VIEW.startsWith('s')){const n=+VIEW.slice(1);printDocs(docsForStage(n),`Tahap ${n} - ${TAHAP[n-1].t}`)}\n  else printDocs(TAHAP.map(t=>docsForStage(t.n)).join(''),'Berkas lengkap 12 tahap');\n});\ndocument.getElementById('btnSave').addEventListener('click',saveRekap);\n\nfunction autoNomor(){let k=N(S.nomor.awal)||1;DOKS.forEach((d,i)=>{if(!d.numbered)return;const tg=S.dok[i].tgl;S.dok[i].no=`${String(k).padStart(3,'0')}/${d.kode}/${S.nomor.akhiran}/${romawi(tg)}/${tahun(tg)}`;k++})}\nfunction blankState(){const s=