        const ak = document.activeElement && document.activeElement.dataset ? document.activeElement.dataset.sap : null;
        const inp = (k, l, tgl) => `<div class="col-6 col-md-4 col-xl-2"><label class="form-label small mb-0">${l}</label><input class="form-control form-control-sm ${tgl ? '' : 'font-monospace'}" data-sap="${k}" ${tgl ? 'type="date"' : 'inputmode="numeric" maxlength="20"'} value="${e(PBJ.ed.sap[k])}" ${entri ? '' : 'disabled'} oninput="PBJ.ed.sap['${k}']=this.value; PBJ_tandaUbah()"></div>`;
        bar.innerHTML = `<div class="pbj-bar card shadow-sm p-2 p-md-3 mb-2">
            <div class="d-flex flex-wrap align-items-center gap-2">
                <button type="button" class="btn btn-sm btn-light border" onclick="pbjTutup()"><i class="fas fa-arrow-left me-1"></i>Daftar paket</button>
                <div class="min-w-0"><div class="fw-bold text-truncate" style="max-width:480px">${e((r && r.nama) || (rec && rec.nama) || 'Paket baru')}</div>
                    <div class="small text-muted font-monospace">${rec ? e(rec.kode) + ' · v' + rec.versi + ' · ' + e((rec.diubahPada || '').slice(0, 16).replace('T', ' ')) + ' ' + e(rec.diubahOleh || '') : 'belum tersimpan'}</div></div>
                ${rec ? badgePBJ(rec.status) : ''}
                <span class="ms-auto"></span>
                <span class="small ${ubah ? 'text-danger fw-semibold' : 'text-success'}" id="pbjStatusSimpan">${PBJ.ed.menyimpan ? '<i class="fas fa-spinner fa-spin me-1"></i>Menyimpan…' : ubah ? '<i class="fas fa-circle me-1" style="font-size:.5rem"></i>Belum disimpan' : rec ? '<i class="fas fa-check me-1"></i>Tersimpan' : ''}</span>
                ${entri ? `<button type="button" class="btn btn-sm btn-light border" onclick="BP_tambah()"><i class="fas fa-clipboard-list me-1"></i>Tarik dari Bon</button>
                <button type="button" class="btn btn-sm btn-primary" onclick="pbjSimpan()" ${PBJ.ed.menyimpan ? 'disabled' : ''}><i class="fas fa-cloud-arrow-up me-1"></i>Simpan</button>` : '<span class="badge text-bg-secondary">Lihat saja</span>'}
                <button type="button" class="btn btn-sm ${bisaKontrak ? 'btn-danger' : 'btn-outline-secondary'}" onclick="pbjBuatKontrak()" ${bisaKontrak ? '' : 'disabled'} title="${rec && rec.noKontrak ? 'Sudah menjadi kontrak ' + e(rec.noKontrak) : 'Aktif setelah status PBJ SIAP CETAK (pemenang valid) dan paket tersimpan'}"><i class="fas fa-file-signature me-1"></i>${rec && rec.noKontrak ? 'Kontrak dibuat' : 'Buat draf kontrak'}</button>
                <button type="button" class="btn btn-sm btn-light border" onclick="pbjEkspor()" title="Unduh JSON paket (format PBJ Studio)"><i class="fas fa-download"></i></button>
            </div>
            ${langkahAlur(rec, r)}
            ${rec && rec.state && rec.state.historis ? panelHistoris(rec) : ''}
            <div class="row g-2 mt-1">${inp('noPR', 'No PR (SAP)')}${inp('tglPR', 'Tgl PR', 1)}${inp('noRFQ', 'No RFQ (SAP)')}${inp('tglRFQ', 'Tgl RFQ', 1)}${inp('noPO', 'No PO (SAP)')}${inp('tglPO', 'Tgl PO', 1)}</div>
            ${rec && rec.noKontrak ? `<div class="small mt-2"><i class="fas fa-link me-1 text-success"></i>Tertaut ke kontrak <a href="#" class="font-monospace" onclick="bukaRegister('semua'); return false;">${e(rec.noKontrak)}</a> — progres, BK, keuangan &amp; pembayaran dipantau di menu masing-masing.</div>` : ''}
        </div>`;
        if (ak) { const el = bar.querySelector(`[data-sap="${ak}"]`); if (el) { el.focus(); try { el.setSelectionRange(el.value.length, el.value.length); } catch (err) { } } }
    }
    window.PBJ_tandaUbah = () => { const s = document.getElementById('pbjStatusSimpan'); if (s) { const u = editorBerubah(); s.className = 'small ' + (u ? 'text-danger fw-semibold' : 'text-success'); s.innerHTML = u ? '<i class="fas fa-circle me-1" style="font-size:.5rem"></i>Belum disimpan' : '<i class="fas fa-check me-1"></i>Tersimpan'; } };
    window.BP_tambah = () => window.__PBJ_HOST.tarikBon();
    async function pbjSimpan(diam) {
        if (!PBJ.ed || !cekDukung()) return false;
        const api = pbjFrameApi(); if (!api) { notif('Editor PBJ belum siap.', 'err'); return false; }
        const st = api.ambilState(), r = api.ringkas(), rec = PBJ.ed.rec;
        const bon = st.items.filter(i => i.bon).map(i => ({ nomor: i.bon.nomor, idx: i.bon.idx, kode: i.bon.kode, wbs: i.bon.wbs, uraian: i.uraian, vol: i.vol, sat: i.satuan, harga: i.hps }));
        const data = Object.assign({ nama: r.nama || (rec && rec.nama) || 'Paket PBJ', tahap: r.tahap, siap: r.siap, pemenang: r.pemenang, hps: r.hps, final: r.final, finalPpn: r.finalPpn, efisiensi: r.efisiensi, bon, state: st }, PBJ.ed.sap);
        if (rec) { data.id = rec.id; data.versi = rec.versi; }
        PBJ.ed.menyimpan = true; renderEditorBar();
        try {
            const res = await regAksi('savePBJ', { data });
            PBJ.ed.rec = res.data; PBJ.ed.id = res.data.id; simpanLokalPBJ(res.data);
            PBJ.ed.simpanAkhir = sidikEditor();
            if (!diam || !rec) notif(res.tidakBerubah ? 'Tidak ada perubahan.' : (rec ? 'Paket ' + res.data.kode + ' tersimpan · v' + res.data.versi : 'Paket ' + res.data.kode + ' dibuat · item Bon terkunci untuk paket ini'), 'ok');
            return true;
        } catch (err) { notif(err.message, 'err'); return false; }
        finally { if (PBJ.ed) { PBJ.ed.menyimpan = false; renderEditorBar(); } }
    }
    window.pbjBuka = id => { const rec = PBJ.data.find(x => x.id === id); if (!rec) return; if (PBJ.ed && editorBerubah()) { notif('Simpan atau tutup paket yang sedang dibuka dulu.', 'err'); bukaTab('pbj'); return; } bukaEditor(rec); };
    window.pbjBaru = () => { if (!cekDukung()) return; bukaEditor(null, { bon: [] }); };
    window.pbjDariBon = () => { if (!cekDukung()) return; bukaPilihBon('baru', list => bukaEditor(null, { bon: list })); };
    window.pbjTutup = () => tutupEditor(false);
    window.pbjSimpan = pbjSimpan;
    window.muatPBJ = muatPBJ;
    window.renderPBJ = renderPBJ;
    window.pbjEkspor = () => {
        const api = pbjFrameApi(); if (!api) return; const st = api.ambilState();
        const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify(st, null, 1)], { type: 'application/json' }));
        a.download = ('PBJ - ' + ((PBJ.ed.rec && PBJ.ed.rec.kode) || '') + ' ' + (st.paket.nama || 'paket')).replace(/[\\/:*?"<>|]/g, '-').slice(0, 100) + '.json'; document.body.appendChild(a); a.click(); a.remove();
    };
    window.pbjImpor = () => {
        if (!cekDukung()) return;
        const i = document.createElement('input'); i.type = 'file'; i.accept = '.json,application/json';
        i.onchange = async () => {
            const f = i.files[0]; if (!f) return;
            try { const o = JSON.parse(await f.text()); const st = o.state && o.state.paket ? o.state : o; if (!st.paket || !st.vendors || !st.items) throw new Error();
                (st.items || []).forEach(it => { delete it.bon; });   // item bon dari berkas luar tidak dipercaya → tautkan ulang lewat "Tarik dari Bon"
                bukaEditor({ id: null, state: st }, {});
            } catch (err) { notif('Berkas bukan JSON PBJ Studio (hasil "Ekspor JSON paket aktif").', 'err'); }
        };
        i.click();
    };
    async function ubahStatus(id, status, alasan) {
        const rec = PBJ.data.find(x => x.id === id); if (!rec) return;
        try { const r = await regAksi('savePBJ', { data: { id, versi: rec.versi, status, alasan } }); simpanLokalPBJ(r.data); notif('Paket ' + r.data.kode + ' → ' + (ST_PBJ[r.data.status] || [r.data.status])[0], 'ok'); renderPBJ(); }
        catch (err) { notif(err.message, 'err'); }
    }
    window.pbjBatal = async id => {
        if (!cekDukung()) return; const rec = PBJ.data.find(x => x.id === id);
        const alasan = await mintaTeks('Batalkan paket ' + rec.kode + ' — ' + rec.nama + '?\nItem Bon di paket ini akan dilepas dan dapat diproses ulang. Data paket tetap tersimpan (status BATAL).', 'Alasan pembatalan (wajib)');
        if (alasan) ubahStatus(id, 'BATAL', alasan);
    };
    window.pbjPulihkan = id => { if (adalahAdmin()) ubahStatus(id, 'PROSES'); };
    window.pbjHapus = async id => {
        if (!adalahAdmin()) return; const rec = PBJ.data.find(x => x.id === id);
        if (!await tanya('Hapus permanen paket ' + rec.kode + ' (status BATAL)?\nTindakan ini tidak dapat dibatalkan. Riwayat tetap tercatat di Log.', { judul: 'Hapus paket PBJ', ok: 'Hapus', bahaya: true })) return;
        try { await regAksi('hapusPBJ', { id }); PBJ.data = PBJ.data.filter(x => x.id !== id); SIMPAN_DATA.set(kunciSnap() + '|pbj', { data: PBJ.data, waktu: Date.now() }); notif('Paket dihapus', 'ok'); renderPBJ(); }
        catch (err) { notif(err.message, 'err'); }
    };
    window.pbjTautkan = async (id, no) => {
        if (!cekDukung()) return; const rec = PBJ.data.find(x => x.id === id);
        if (!await tanya('Tautkan paket ' + rec.kode + ' ke kontrak ' + no + '?', { judul: 'Tautkan kontrak', ok: 'Tautkan', bahaya: false })) return;
        try { const r = await regAksi('savePBJ', { data: { id, versi: rec.versi, noKontrak: no } }); simpanLokalPBJ(r.data); notif('Tertaut ke ' + no, 'ok'); renderPBJ(); } catch (err) { notif(err.message, 'err'); }
    };
    function mintaTeks(pesan, label) {
        return new Promise(ok => {
            const m = pastikanModal('modalTeks', 'Konfirmasi', 'modal-md');
            document.getElementById('modalTeksIsi').innerHTML = `<div class="small mb-2" style="white-space:pre-line">${e(pesan)}</div><label class="form-label small">${e(label)}</label><textarea class="form-control" id="mtIsi" rows="2"></textarea>`;
            document.getElementById('modalTeksKaki').innerHTML = `<button class="btn btn-light border" data-bs-dismiss="modal">Batal</button><button class="btn btn-danger" id="mtOk">Lanjutkan</button>`;
            let hasil = '';
            document.getElementById('mtOk').onclick = () => { const v = document.getElementById('mtIsi').value.trim(); if (!v) { document.getElementById('mtIsi').classList.add('is-invalid'); return; } hasil = v; tampilModal('modalTeks', false); };
            m.addEventListener('hidden.bs.modal', () => ok(hasil), { once: true });
            tampilModal('modalTeks', true);
        });
    }

    /* =================================================================
       8. PBJ → KONTRAK (draf Register) — memakai format nomor kontrak yang sama
       ================================================================= */
    const JENIS_SEMUA = [...JENIS_MATERIAL, ...JENIS_SERVICE];
    const KK = { st: null, r: null, rec: null };
    window.pbjBuatKontrak = async () => {
        if (!PBJ.ed || !cekDukung()) return;
        const api = pbjFrameApi(); if (!api) return;
        if (editorBerubah()) { if (!await pbjSimpan(true)) return; }
        const rec = PBJ.ed.rec, r = api.ringkas(), st = api.ambilState();
        if (!rec) { notif('Simpan paket dulu.', 'err'); return; }
        if (rec.noKontrak) { notif('Paket ini sudah menjadi kontrak ' + rec.noKontrak + '.', 'err'); return; }
        if (!r.siap || !r.winId) { notif('PBJ belum SIAP CETAK: pastikan peserta pembanding (min. 3) & pemenang valid.', 'err'); return; }
        KK.st = st; KK.r = r; KK.rec = rec;
        const jenis = (String(r.jenisPek).toUpperCase().match(/\b(SPPM|SPM|SPPP|SPKP|SPKU|SPSA|SPK)\b/) || [])[1] || '';
        const tgl = r.tglSppbj || hariIniISO(), th = Number(tgl.slice(0, 4)) || new Date().getFullYear(), bl = NAMA_BULAN[(Number(tgl.slice(5, 7)) || 1) - 1];
        const v = (getVendorList() || []).find(x => String(x.name || '').trim().toLowerCase() === r.pemenang.trim().toLowerCase());
        pastikanModal('modalKontrakPBJ', '<i class="fas fa-file-signature me-2"></i>Buat draf kontrak dari paket PBJ');
        const items = st.items.map(it => ({ kode: (it.bon && it.bon.kode) || '', uraian: it.uraian, vol: N(it.vol), sat: it.satuan || '', harga: N((it.final || {})[r.winId]), wbs: (it.bon && it.bon.wbs) || '', noPermintaan: (it.bon && it.bon.nomor) || '' }));
        KK.items = items;
        document.getElementById('modalKontrakPBJIsi').innerHTML = `
            <div class="alert alert-info small py-2"><i class="fas fa-circle-info me-1"></i>Kontrak dibuat sebagai <b>Draf di Register Kontrak</b> (alur lama tetap: lengkapi WBS/PR/RFQ/PO/TOP → Posting). Harga satuan = harga final pemenang (belum PPN). Paket ${e(rec.kode)} akan tertaut ke kontrak ini.</div>
            <div class="row g-2">
                <div class="col-md-3"><label class="form-label small">Jenis kontrak</label><select class="form-select form-select-sm" id="kkJenis" onchange="KK_no()">${['', ...JENIS_SEMUA].map(j => `<option ${j === jenis ? 'selected' : ''} value="${j}">${j || '-- pilih --'}</option>`).join('')}</select></div>
                <div class="col-md-2"><label class="form-label small">Tahun</label><input type="number" class="form-control form-control-sm" id="kkTahun" value="${th}" oninput="KK_no()"></div>
                <div class="col-md-2"><label class="form-label small">Bulan</label><select class="form-select form-select-sm" id="kkBulan">${NAMA_BULAN.map(b => `<option ${b === bl ? 'selected' : ''}>${b}</option>`).join('')}</select></div>
                <div class="col-md-2"><label class="form-label small">No urut</label><input class="form-control form-control-sm font-monospace" id="kkUrut" oninput="KK_no(true)"></div>
                <div class="col-md-3"><label class="form-label small">No kontrak</label><input class="form-control form-control-sm font-monospace" id="kkNo" readonly><div class="small" id="kkNoInfo"></div></div>
                <div class="col-md-6"><label class="form-label small">Vendor pemenang</label><input class="form-control form-control-sm" id="kkVendor" value="${e(r.pemenang)}"></div>
                <div class="col-md-2"><label class="form-label small">ID vendor (SAP)</label><input class="form-control form-control-sm font-monospace" id="kkIdVendor" value="${e(v ? v.id : '')}" placeholder="${v ? '' : 'tidak ada di Master'}"></div>
                <div class="col-md-2"><label class="form-label small">Tgl kontrak</label><input type="date" class="form-control form-control-sm" id="kkTgl" value="${e(tgl)}"></div>
                <div class="col-md-2"><label class="form-label small">Tgl selesai</label><input type="date" class="form-control form-control-sm" id="kkSelesai"></div>
                <div class="col-md-3"><label class="form-label small">No PR</label><input class="form-control form-control-sm font-monospace" id="kkPR" value="${e(rec.noPR || '')}"></div>
                <div class="col-md-3"><label class="form-label small">No RFQ</label><input class="form-control form-control-sm font-monospace" id="kkRFQ" value="${e(rec.noRFQ || '')}"></div>
                <div class="col-md-3"><label class="form-label small">No PO</label><input class="form-control form-control-sm font-monospace" id="kkPO" value="${e(rec.noPO || '')}"></div>
                <div class="col-md-3"><label class="form-label small">TOP (syarat bayar)</label><input class="form-control form-control-sm" id="kkTop" value="${e(r.bayar)}"></div>
            </div>
            <div class="table-responsive mt-3"><table class="table table-sm align-middle"><thead class="table-light"><tr><th>#</th><th>Kode</th><th>Uraian</th><th class="text-end">Vol</th><th>Sat</th><th class="text-end">Harsat final</th><th class="text-end">Jumlah</th><th>WBS</th><th>Bon</th></tr></thead>
            <tbody>${items.map((it, i) => `<tr><td>${i + 1}</td><td><code>${e(it.kode || '-')}</code></td><td>${e(it.uraian)}</td><td class="text-end">${fmtAngka(it.vol)}</td><td>${e(it.sat)}</td><td class="text-end">${fmtRp(it.harga)}</td><td class="text-end">${fmtRp(it.vol * it.harga)}</td><td class="font-monospace small">${e(it.wbs || '-')}</td><td class="font-monospace small">${e(it.noPermintaan ? noBonPendek(it.noPermintaan) : '-')}</td></tr>`).join('')}</tbody>
            <tfoot><tr class="fw-bold"><td colspan="6" class="text-end">Nilai kontrak (belum PPN)</td><td class="text-end">${fmtRp(items.reduce((a, i) => a + i.vol * i.harga, 0))}</td><td colspan="2"></td></tr></tfoot></table></div>
            ${items.some(i => !i.harga) ? '<div class="alert alert-danger small py-2">Ada item tanpa harga final pemenang. Lengkapi di Tahap 3 PBJ.</div>' : ''}`;
        document.getElementById('modalKontrakPBJKaki').innerHTML = `<button class="btn btn-light border" data-bs-dismiss="modal">Batal</button><button class="btn btn-danger" id="kkOk" onclick="KK_simpan()"><i class="fas fa-file-signature me-1"></i>Buat draf kontrak di Register</button>`;
        KK_no(); tampilModal('modalKontrakPBJ', true);
    };
    window.KK_no = manual => {
        const j = document.getElementById('kkJenis').value, th = document.getElementById('kkTahun').value, u = document.getElementById('kkUrut');
        if (!manual) { const s = saranNoUrut(j, th); u.value = s ? String(s).padStart(3, '0') : ''; }
        const no = j && u.value.trim() ? `${/^\d+$/.test(u.value.trim()) ? u.value.trim().padStart(3, '0') : u.value.trim()}/${j}/${NO_KONTRAK_TENGAH}/${th}` : '';
        const kno = document.getElementById('kkNo'); kno.value = no;
        const dup = no && (noKontrakSudahAda(no) || (REG.data || []).find(r => r.noKontrak === no));
        kno.classList.toggle('is-invalid', !!dup);
        document.getElementById('kkNoInfo').innerHTML = dup ? `<span class="text-danger">Nomor sudah dipakai (${e(dup.namaVendor || '')})</span>` : no ? '<span class="text-success">Nomor tersedia</span>' : '';
    };
    window.KK_simpan = async () => {
        const g = id => document.getElementById(id).value.trim();
        const no = g('kkNo'), jenis = g('kkJenis');
        if (!jenis || !no) { notif('Pilih jenis kontrak & no urut.', 'err'); return; }
        if (noKontrakSudahAda(no) || (REG.data || []).some(r => r.noKontrak === no)) { notif('No kontrak ' + no + ' sudah dipakai.', 'err'); return; }
        if (!g('kkVendor')) { notif('Nama vendor wajib diisi.', 'err'); return; }
        if (KK.items.some(i => !i.harga || !i.vol)) { notif('Ada item tanpa volume / harga final.', 'err'); return; }
        const btn = document.getElementById('kkOk'); btn.disabled = true;
        try {
            const res = await regAksi('save', { data: { noKontrak: no, jenisKontrak: jenis, noUrut: Number(no.split('/')[0]) || '', tahun: Number(g('kkTahun')) || '', bulan: g('kkBulan'),
                idVendor: g('kkIdVendor'), namaVendor: g('kkVendor'), kelompok: KELOMPOK_MAP[jenis] || '', tglKontrak: g('kkTgl'), tglSelesai: g('kkSelesai'),
                catatan: 'Dari paket ' + KK.rec.kode + ' — ' + KK.r.nama, items: KK.items, noPR: g('kkPR'), noRFQ: g('kkRFQ'), noPO: g('kkPO'), top: g('kkTop') } });
            let taut;
            try { taut = await regAksi('savePBJ', { data: { id: KK.rec.id, versi: KK.rec.versi, noKontrak: res.data.noKontrak, noPR: g('kkPR'), noRFQ: g('kkRFQ'), noPO: g('kkPO') } }); }
            catch (err) { notif('Kontrak ' + no + ' dibuat, tetapi tautan ke paket gagal: ' + err.message + '. Gunakan tombol "Tautkan" di daftar paket.', 'err'); }
            if (taut) { simpanLokalPBJ(taut.data); if (PBJ.ed && PBJ.ed.id === taut.data.id) { PBJ.ed.rec = taut.data; ['noPR', 'noRFQ', 'noPO'].forEach(k => PBJ.ed.sap[k] = taut.data[k] || ''); PBJ.ed.simpanAkhir = sidikEditor(); } }
            tampilModal('modalKontrakPBJ', false);
            notif('Draf kontrak ' + no + ' dibuat di Register' + (taut ? ' & tertaut ke ' + KK.rec.kode : ''), 'ok');
            await muatRegister();
            renderEditorBar();
        } catch (err) { notif(err.message, 'err'); }
        finally { btn.disabled = false; }
    };

    /* =================================================================
       9. KEUANGAN & PEMBAYARAN per tagihan (BK)
       ================================================================= */
    const ST_BAYAR = { BELUM: ['Belum diajukan', 'text-bg-secondary', '#8494AE'], DIAJUKAN: ['Diajukan', 'text-bg-warning', '#C27412'], DIVERIFIKASI: ['Diverifikasi', 'text-bg-info', '#1763B3'], DIBAYAR: ['Dibayar', 'text-bg-success', '#2E9E5B'], DITUNDA: ['Ditunda', 'text-bg-danger', '#E3343F'] };
    const badgeBayar = s => { const x = ST_BAYAR[s] || ST_BAYAR.BELUM; return `<span class="badge ${x[1]}">${x[0]}</span>`; };
    function keuCek(e2) {
        const a = alurDok(e2), kode = e2.kodeBA || 'BAPP', kg = e2.keuangan || {};
        const terima = a.wajib.filter(k => k !== 'miro');
        const cek = [
            ['ba', 'BA ' + kode + ' terbit', !!e2.baTerbit, 'sap'],
            ['tagihan', 'Surat tagihan / invoice', !!String(e2.tagihan || '').trim(), 'sap'],
            ['faktur', 'Faktur pajak', !!String(e2.faktur || '').trim(), 'sap'],
            ['terima', terima.map(k => k.toUpperCase()).join(' / ') + ' (SAP)', terima.every(k => String(e2[k] || '').trim()), 'sap'],
            ['miro', 'MIRO (SAP)', !!String(e2.miro || '').trim(), 'sap']
        ];
        KEU_DOK.forEach(d => { if (d[2] === 'BAPM' && kode !== 'BAPM') return; if (d[2] === 'JASA' && kode === 'BAPM') return; cek.push([d[0], d[1], !!(kg[d[0]] && kg[d[0]].ok), 'manual']); });
        const n = cek.filter(c => c[2]).length;
        return { cek, n, total: cek.length, lengkap: n === cek.length };
    }
    window.keuCek = keuCek;
    const KEU = { status: '', cari: '', periode: '', dok: '' };
