           · tanggal kejadian asli (dari dokumen) dipisah dari tanggal input aplikasi
           · selisih nilai / skor hanya DITAMPILKAN untuk verifikasi, data sumber tidak diubah
       ================================================================= */
    const KRIT_LABEL = ['Status Rekanan (WAVE)', 'Kinerja Rekanan (WAVE)', 'SKN (WAVE)', 'Anti Penyuapan', 'Harga Penawaran Final', 'Progress & Cara Bayar', 'Uang Muka', 'Retensi', 'Metode Kerja', 'Alat', 'CV & Struktur Organisasi',
        'Dukungan Tender', 'Dukungan Kinerja', 'Mutu', 'Life Cycle Analysis', 'Schedule', 'Persentase TKDN', 'Preferensi Harga'];
    const KRIT_HARGA = 4;   // kriteria "Harga Penawaran Final" dihitung otomatis oleh PBJ Studio = MIN(1; HPS / harga final)
    const H = { st: null, nama: '', hash: '', bon: '', peta: [], kontrak: '' };
    window.H_IMPOR = H;
    const fmtTgl = t => t ? tglID(t) : '—';
    const nilaiVendor = (st, vid, mode) => st.items.reduce((a, it) => a + N(it.vol) * N((it[mode] || {})[vid]), 0);
    const hpsDari = st => st.items.reduce((a, it) => a + N(it.vol) * N(it.hps), 0);
    function skorDari(st, vid, otomatis) {
        const hps = hpsDari(st), fin = nilaiVendor(st, vid, 'final'), n = (st.nilai || {})[vid] || [];
        return (st.bobot || []).reduce((a, b, i) => a + N(b) * (otomatis && i === KRIT_HARGA ? (fin > 0 ? Math.min(1, hps / fin) : 0) : N(n[i])), 0);
    }
    function sidikTeks(t) { let h = 0; for (let i = 0; i < t.length; i++) h = (h * 31 + t.charCodeAt(i)) >>> 0; return h.toString(36) + '-' + t.length.toString(36); }
    const angkaID = s => Number(String(s).replace(/\./g, '').replace(',', '.'));
    function kataKunci(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 2 && !['termasuk', 'frontal', 'frame', 'phase', 'pekerjaan', 'rubber'].includes(w)); }
    function mirip(a, b) { const A = kataKunci(a), B = kataKunci(b); if (!A.length || !B.length) return 0; return A.filter(w => B.some(x => x.includes(w) || w.includes(x))).length / Math.max(A.length, B.length); }
    const itemBerharga = it => !!(String(it.kode || '').trim() || N(it.harga) > 0);

    /* --- pencocokan otomatis: item PBJ ↔ baris Bon --- */
    function petaBon(st, bon) {
        const pakai = new Set(), cal = (bon.items || []).map((it, idx) => ({ it, idx })).filter(x => itemBerharga(x.it));
        return st.items.map(pi => {
