            const arsip = angkaID(m[2]), file = skorDari(st, v.id, false), app = skorDari(st, v.id, true);
            const sama = Math.abs(arsip - app) < 0.005;
            (sama ? ok : beda)('Skor PB-01.2 · ' + v.nama, 'Arsip: ' + arsip.toLocaleString('id-ID', { minimumFractionDigits: 2 }), 'Aplikasi: ' + app.toLocaleString('id-ID', { minimumFractionDigits: 2 }) + (Math.abs(file - app) > 0.005 ? ' (nilai di berkas: ' + file.toLocaleString('id-ID', { minimumFractionDigits: 2 }) + ')' : ''),
                sama ? '' : 'Kriteria "Harga Penawaran Final" dihitung otomatis = MIN(1; HPS/final) = ' + Math.min(1, hps / nilaiVendor(st, v.id, 'final')).toFixed(4) + ', sedangkan berkas mencatat ' + N(((st.nilai || {})[v.id] || [])[KRIT_HARGA]));
