            const nk = items.reduce((a, i) => a + N(i.volume || i.volumeKontrak) * N(i.hargaSatuan), 0);
            (Math.abs(nk - fin) < 1 ? ok : beda)('Nilai kontrak ' + kon.split('/').slice(0, 2).join('/') + ' (DPP)', 'Kontrak: ' + fmtRp(nk), 'Final PBJ: ' + fmtRp(fin), '');
            const tak = st.items.filter(pi => !items.some(i => N(i.volume || i.volumeKontrak) === N(pi.vol) && Math.abs(N(i.hargaSatuan) - N(pi.final[win.id])) < 1)).length;
            (tak ? beda : ok)('Item kontrak vs harga final', items.length + ' item berharga di kontrak', st.items.length + ' item PBJ' + (tak ? ' · ' + tak + ' tidak cocok' : ' · semua cocok'), '');
