            else (vk.toLowerCase().replace(/\bpt\b|[.,]/g, '').trim() === win.nama.toLowerCase().replace(/\bpt\b|[.,]/g, '').trim() ? ok : beda)('Vendor pada kontrak', 'Kontrak: ' + vk, 'Pemenang: ' + win.nama, '');
