    const DOKS_NAMA = ['Undangan Tender', 'Undangan Aanwijzing', 'BA Aanwijzing', 'RFQ', 'Undangan Klarifikasi & Negosiasi', 'BA Klarifikasi & Negosiasi', 'Evaluasi Harga (PB-01A)', 'Evaluasi Penawaran (PB-01.2)', 'BA Penentuan Pemenang (PB-10)', 'Pengumuman Pemenang', 'Laporan Usulan', 'Penetapan Pemenang (SPPBJ)'];
