    function alokItem(nomor, idx) { return alokAktif().filter(a => a.bonNomor === nomor && Number(a.bonIdx) === Number(idx)); }
    function volAlok(nomor, idx) { return alokItem(nomor, idx).reduce((a, x) => a + N(x.volume), 0); }
