                const A = alokAktif().filter(a => a.bonNomor === p.nomor); if (!A.length) return r;
                const sudah = (r.sudah || []).slice(), alok = {};
                (p.items || []).forEach((it, i) => { const v = A.filter(a => Number(a.bonIdx) === i).reduce((s, a) => s + N(a.volume), 0); if (v > 0) alok[i] = v; if (v > 0 && v >= N(it.vol) - 1e-9) sudah[i] = true; });
