            } catch (err) { return r; }
        };
    })();
    function daftarKontrakPilihan() {
        const m = new Map();
        ((typeof RINGKASAN !== 'undefined' && RINGKASAN) || []).forEach(g => { if (kontrakValid(g.key)) m.set(g.key, { no: g.key, vendor: g.namaVendor || '', sumber: g.baru ? 'Register' : 'Master' }); });
        (REG.data || []).forEach(r => { if (r.noKontrak) m.set(r.noKontrak, { no: r.noKontrak, vendor: r.namaVendor || '', sumber: r.diposting ? 'Register' : 'Draf Register' }); });
        (PBJ.data || []).forEach(p => { if (p.status !== 'BATAL' && p.noKontrak && !m.has(p.noKontrak)) m.set(p.noKontrak, { no: p.noKontrak, vendor: p.pemenang || '', sumber: 'PBJ' }); });
        return [...m.values()].sort((a, b) => urutNomor(b.no) - urutNomor(a.no) || a.no.localeCompare(b.no));
