        const s = new Set();
        ((typeof RINGKASAN !== 'undefined' && RINGKASAN) || []).forEach(g => (g.items || []).forEach(i => { const w = String(i.wbs || '').trim(); if (w) s.add(w); }));
        (PMT.data || []).forEach(p => { if (p.wbs) s.add(String(p.wbs).trim()); (p.items || []).forEach(i => { if (i.wbs) s.add(String(i.wbs).trim()); }); });
