    function renderAlokasi() {
        const isi = document.getElementById('mp214AlIsi'); if (!isi) return;
        const p = (PMT.data || []).find(x => x.nomor === AL.nomor); if (!p) return;
        const entri = bolehEntri() && MP.dukung !== false, bisaBatal = fitur('alokasiBatal');
