            const A = alokItem(p.nomor, i), v = A.reduce((a, x) => a + N(x.volume), 0), harga = N(it.harga), sisa = Math.max(N(it.vol) - v, 0);
            const lebih = v > N(it.vol) + 1e-9, faktor = lebih && v ? N(it.vol) / v : 1;   // Bon diubah setelah dialokasikan → ringkasan dibatasi volume Bon
