            const tt = kontrakTertaut(p, i), konI = tt.length ? kon.filter(k => tt.includes(k.no)).concat(tt.filter(no => !pk.has(no)).map(no => ({ no, vendor: '', sumber: 'tertaut' }))) : kon;
