    /* =================================================================
       10. [2.1.5] KUNCI SERVER PERMANEN
           Setelah Admin terhubung ke server yang benar (Code.gs ≥ v2.4) alamatnya dikunci di perangkat.
           · Saat aplikasi dibuka: bila alamat tersimpan berbeda dari alamat terkunci → dikembalikan otomatis.
           · Ganti alamat hanya diterima bila server baru menjawab versi ≥ versi terkunci (kunci ikut pindah).
           · Server terkunci tiba-tiba menjawab versi lama → peringatan jelas (deployment diturunkan).
       ================================================================= */
    const KUNCI_SRV = 'JICT_SERVER_KUNCI', MIN_VERSI = 2.4;
    const angkaVersi = v => { const m = String(v || '').match(/^(\d+)\.(\d+)(?:\.(\d+))?/); return m ? Number(m[1]) + Number(m[2]) / 10 + (Number(m[3] || 0)) / 1000 : 0; };
    const bacaKunci = () => { try { return JSON.parse(localStorage.getItem(KUNCI_SRV) || 'null'); } catch (err) { return null; } };
    const tulisKunci = k => { try { if (k) localStorage.setItem(KUNCI_SRV, JSON.stringify(k)); else localStorage.removeItem(KUNCI_SRV); } catch (err) { } };
    const urlSah = u => /^https:\/\/script\.google(usercontent)?\.com\/macros\/s\/[\w-]+\/exec$/.test(String(u || '').trim());
    const ujungUrl = u => '…' + String(u || '').replace(/\/exec.*$/, '').slice(-10) + '/exec';
    async function pingUrl(url) {
        try { const r = await fetch(url + '?action=ping&t=' + Date.now(), { redirect: 'follow', cache: 'no-store' }).then(x => x.json()); return { ok: !!r.ok, versi: r.versiServer || '' }; }
        catch (err) { return { ok: false, versi: '', galat: err.message }; }
    }
    // 1) dijalankan sebelum initRegister membaca alamat → alamat terkunci selalu dipakai
    (function pulihkanAlamat() {
        if (window.desktop && window.desktop.aplikasi && window.desktop.server) return;   // [2.1.9] Windows: config.json = sumber alamat
        const k = bacaKunci(); if (!k || !urlSah(k.url)) return;
        let kini = ''; try { kini = localStorage.getItem(KUNCI_URL) || ''; } catch (err) { }
        if (kini !== k.url) { try { localStorage.setItem(KUNCI_URL, k.url); } catch (err) { } window.__kunciDipulihkan = kini || '(kosong)'; }
    })();
    function kunciKe(url, versi, sumber) {
        const k = { url, versi, pada: new Date().toISOString(), oleh: (REG.sesi && REG.sesi.nama) || '', sumber: sumber || '' };
        tulisKunci(k); return k;
    }
    // 2) ganti alamat server: hanya ke server yang versinya tidak lebih lama dari kunci
    async function izinkanAlamat(url) {
        const k = bacaKunci(); if (!url) return !k ? true : (notif('Server dikunci ke ' + ujungUrl(k.url) + '. Mode lokal tidak dapat dipilih selama kunci aktif (Admin › Pembaruan › Lepas kunci).', 'err'), false);
        const p = await pingUrl(url);
        if (k && url !== k.url) {
            if (!p.ok || angkaVersi(p.versi) < angkaVersi(k.versi)) {
                notif('Alamat ditolak: server ' + ujungUrl(url) + ' menjawab ' + (p.versi ? 'v' + p.versi : 'versi lama / tidak dapat dihubungi') + ', sedangkan server terkunci v' + k.versi + '. Aplikasi tetap memakai ' + ujungUrl(k.url) + '.', 'err');
                return false;
            }
