        }
        if (!k && p.ok && angkaVersi(p.versi) >= MIN_VERSI) { kunciKe(url, p.versi, 'simpan'); notif('Server v' + p.versi + ' tersimpan & dikunci permanen di perangkat ini.', 'ok'); }
        else if (!k && !(angkaVersi(p.versi) >= MIN_VERSI)) notif('Peringatan: server ' + ujungUrl(url) + ' menjawab ' + (p.versi ? 'v' + p.versi : 'versi lama') + ' — belum Code.gs v2.4. Alamat disimpan tetapi TIDAK dikunci.', 'err');
        return true;
