      + (diisi.some(z => z.saran) ? `<div><i class="fas fa-circle-info me-1"></i>${diisi.filter(z => z.saran).length} dokumen tersedia di Arsip Vendor${r.verified ? ' (checklist sudah diverifikasi — tidak diubah)' : ''}.</div>` : '')
