  const TETAP = ['KSO', 'JO', 'PT', 'PT.', 'CV', 'BUMN', 'TBK.', 'II', 'III', 'IV'];
  function judul(t) {
    t = String(t || '');
    if (t !== t.toUpperCase()) return t;
    return t.split(/(\s+)/).map(w => { const u = w.toUpperCase(); if (KECIL[u]) return KECIL[u]; if (TETAP.includes(u)) return u === 'TBK.' ? 'Tbk.' : u; return w.charAt(0) + w.slice(1).toLowerCase(); }).join('').replace(/\s-\s/g, ' – ');
  }
  function turunan() {
    const nama = (typeof PROYEK !== 'undefined' && PROYEK.kso) || 'WASKITA - NINDYA KSO';
    const kso = /\bKSO\b|\bJ\.?O\b|JOINT/i.test(nama);
    return { bentuk: kso ? 'KSO' : 'TUNGGAL', nama, singkatan: (nama.replace(/^PT\.?\s+/i, '').trim().charAt(0) || 'W').toUpperCase(), anggota: [], unit: '', asal: 'proyek' };
  }
  function identitas() {
    const d = ID.data || lsGet('JICT_IDENTITAS_' + pid(), null);
    if (d && d.nama) return Object.assign({ anggota: [], unit: '', singkatan: 'W', bentuk: 'TUNGGAL' }, d, { asal: ID.data ? 'server' : 'cache' });
    return turunan();
  }
  window.mp224Identitas = identitas;
  window.mp224Pelaksana = gaya => { const n = identitas().nama; return gaya === 'judul' ? judul(n) : n; };
  const bawaan = n => String(n || '').replace(/\s+/g, ' ').trim().toUpperCase().replace(/\s*[-–—]\s*/g, '-') === 'WASKITA-NINDYA KSO';
  function gantiTeks(s) { const idt = identitas(); if (bawaan(idt.nama)) return s; return String(s).replace(RE_DEF, m => m === m.toUpperCase() ? idt.nama.toUpperCase() : judul(idt.nama)); }
