      <div class="mp219-card"><div class="mp219-fl"><div class="mp219-chips">${chip('', 'Semua', ada.filter(x => x.s !== 'TIDAK_LENGKAP').length)}${['BELUM', 'LOLOS', 'REVISI', 'KEDALUWARSA'].map(s => chip(s, SV[s][0], n(s))).join('')}</div>
