  function progres(id, j) {
    const ik = { antre: 'fa-circle text-muted', proses: 'fa-spinner fa-spin text-primary', ok: 'fa-circle-check text-success', cache: 'fa-database text-success', gagal: 'fa-circle-xmark text-danger' };
