      let r = null, g = null, n = 0;
      for (; ; n++) {
        r = null; g = null;
        try { r = await rp.apply(this, arguments); } catch (e) { g = e; }
        const s = g ? teks(g) : (r && r.ok === false ? teks(r.error) : '');
        const sibuk = SIBUK.test(s);
