(function () {
  'use strict';
  if (window.__MP260__) return;
  window.__MP260__ = true;
  const PREFIX = 'SISTEM-PERBAIKAN-REGISTER|';
  const E = v => (typeof escHtml === 'function' ? escHtml(v == null ? '' : String(v)) : String(v == null ? '' : v).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])));
