    else if (adm() && srv('vtManual')) out.push('<div class="mp2618-al warn">AI membaca dokumen tagihan (NPWP, KTP, rekening dikirim ke penyedia AI). <button type="button" class="btn btn-sm mp219-btn-o" onclick="mp2620Manual(true)">Aktifkan mode manual</button></div>');
    if (!seg.length && !manual()) out.push(`<div class="mp2618-al no"><b>AI tidak menemukan dokumen di bundel ini.</b> Penyebab umum: hasil pindai buram/miring, penyedia AI yang hanya membaca lapisan teks PDF (mis. model OpenRouter tanpa dukungan PDF), atau PDF terkunci. ${adm() ? 'Coba <b>Baca ulang dengan penyedia AI lain</b> (disarankan Google Gemini / Anthropic Claude), ' : 'Minta Admin membaca ulang dengan penyedia lain, '}atau petakan halaman secara manual di bawah.</div>`);
    if (B.dariTeks) out.push('<div class="mp2618-al warn"><b>Dipisahkan dari lapisan teks PDF</b> — AI tidak membaca isi pindaian; nilai, meterai & tanda tangan belum terbaca. Periksa pemetaan; baris checklist tetap diverifikasi AI pada tahap akhir.</div>');
    if (/openrouter/i.test(B.provider || '') && (!seg.length || B.dariTeks)) out.push('<div class="mp2618-al warn">Penyedia <b>OpenRouter</b>: pastikan model yang dipilih mendukung PDF/gambar; model teks saja hanya membaca lapisan teks sehingga bundel hasil pindai terbaca kosong.</div>');
    const ket = [];
    if (info) ket.push('Lapisan teks: ' + info.berteks + '/' + info.halaman + ' halaman' + (info.judul ? ' · ' + info.judul + ' judul dikenali tanpa AI' : '') + (info.berteks < info.halaman ? ' · ' + (info.halaman - info.berteks) + ' halaman hasil pindai' : ''));
