      kabar('Pembentuk Tagihan: ' + S.jalan.ok + ' paket terbentuk' + (S.jalan.gagal.length ? ', ' + S.jalan.gagal.length + ' gagal (lihat daftar)' : '') + '.', S.jalan.gagal.length ? 'warning' : 'ok');
